    window.addEventListener('clear-character-selection', onWindowClearCharacterSelection);

    // =========================================================================
    // LOBBY BENCH & SEAT SPOTS + FLOATING 3D DISC INDICATORS & 3RD-PERSON SITTING CAMERA
    // =========================================================================
