    let hasLastRenderedCamPose = false;
    let npcPortraitOrbitYaw = 0;
    let npcPortraitOrbitPitch = 0;
    let npcPortraitDistanceScale: number = NPC_DIALOGUE_ORBIT_BOUNDS.defaultDistanceScale;
    let npcPortraitSmoothedYaw = 0;
    let npcPortraitSmoothedPitch = 0;
    let npcPortraitSmoothedDistScale: number = NPC_DIALOGUE_ORBIT_BOUNDS.defaultDistanceScale;
    let isOrbitingNpcPortrait = false;
    let npcPortraitOrbitDragStart = {
      x: 0,
      y: 0,
      yaw: 0,
      pitch: 0,
    };
    const resetNpcPortraitInspectCamera = (
      defaultDistanceScale: number = NPC_DIALOGUE_ORBIT_BOUNDS.defaultDistanceScale,
    ) => {
      const clampedScale = clampNpcDialoguePortraitOrbit({
        portraitDistanceScale: defaultDistanceScale,
        minDistanceScale: citySelfieCameraOpen ? 0.56 : undefined,
        minYawOffsetRad: citySelfieCameraOpen ? -Math.PI : undefined,
        maxYawOffsetRad: citySelfieCameraOpen ? Math.PI : undefined,
      }).portraitDistanceScale;
      npcPortraitOrbitYaw = 0;
      npcPortraitOrbitPitch = 0;
      npcPortraitDistanceScale = clampedScale;
      npcPortraitSmoothedYaw = 0;
      npcPortraitSmoothedPitch = 0;
      npcPortraitSmoothedDistScale = clampedScale;
      isOrbitingNpcPortrait = false;
    };
    const isNpcPortraitInspectActive = () =>
      npcCameraMode === 'npc_merchant' ||
      (npcCameraMode === 'none' && Boolean(citizenPortraitState)) ||
      (npcCameraMode === 'cafe_interior' && activeCitizenDialogueId === 'citizen_mira') ||
      Boolean(posePortraitState);
    const onCitizenDialogueOpenState = (ev: Event) => {
      const customEv = ev as CustomEvent<{ isOpen?: boolean; citizenId?: string | null }>;
      const nextId = customEv.detail?.isOpen ? (customEv.detail.citizenId ?? null) : null;
      if (nextId !== activeCitizenDialogueId) {
        resetNpcPortraitInspectCamera();
      }
      activeCitizenDialogueId = nextId;
    };
    const onPoseInspectOpenState = (ev: Event) => {
      const customEv = ev as CustomEvent<{
        isQuickPoseOpen?: boolean;
        pairedTargetId?: string | null;
      }>;
      poseModalInspectOpen = Boolean(customEv.detail?.isQuickPoseOpen);
      pairedModalInspectTargetId = customEv.detail?.pairedTargetId
        ? String(customEv.detail.pairedTargetId)
        : null;
    };
    window.addEventListener('citizen-dialogue-open-state', onCitizenDialogueOpenState);
    window.addEventListener('pose-inspect-open-state', onPoseInspectOpenState);
    let updateDirectDomPrompts: () => void = () => {};

    // 2. Scene, Camera & Authentic Buddies Blitz Warm Afternoon Sun Lighting
    const scene = new THREE.Scene();
    scene.background = new THREE.Color('#7fd8ff');
    const initialHorizonFog = evaluateHorizonFogAndFarClip({ mode: 'gameplay' });
    scene.fog = new THREE.Fog(
      initialHorizonFog.fogColorHex,
      initialHorizonFog.fogNear,
      initialHorizonFog.fogFar,
    );
    scene.add(characterSelectionRing);

    // Procedural Makoto Shinkai / Ghibli Cel-Shaded Sky Dome Shader
    const initialSunDir = getBlitzDefaultLightDirection().normalize();
    const animeSkyUniforms = {
      uTime: { value: 0 },
      uSunDir: { value: initialSunDir.clone() },
      uZenithColor: { value: new THREE.Color('#1b5eb8') },
      uMidSkyColor: { value: new THREE.Color('#3b99f0') },
      uHorizonSkyColor: { value: new THREE.Color('#8be0ff') },
      uHorizonGlowColor: { value: new THREE.Color('#fff1cf') },
      uGroundBounceColor: { value: new THREE.Color('#8ec8e8') },
      uSunColor: { value: new THREE.Color('#fff9e6') },
      uCloudLitColor: { value: new THREE.Color('#fffdf9') },
      uCloudMidColor: { value: new THREE.Color('#d7e8ff') },
      uCloudShadowColor: { value: new THREE.Color('#a6c2e8') },
    };

    const animeSkyGeo = new THREE.SphereGeometry(620, 64, 48);
    const animeSkyMat = new THREE.ShaderMaterial({
      uniforms: animeSkyUniforms,
      side: THREE.BackSide,
      depthWrite: false,
      depthTest: true,
      toneMapped: false,
      fog: false,
      vertexShader: /* glsl */ `
        varying vec3 vWorldDir;
        void main() {
          vWorldDir = normalize(position);
          vec4 clipPos = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          gl_Position = vec4(clipPos.xy, clipPos.w * 0.9998, clipPos.w);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform float uTime;
        uniform vec3 uSunDir;
        uniform vec3 uZenithColor;
        uniform vec3 uMidSkyColor;
        uniform vec3 uHorizonSkyColor;
        uniform vec3 uHorizonGlowColor;
        uniform vec3 uGroundBounceColor;
        uniform vec3 uSunColor;
        uniform vec3 uCloudLitColor;
        uniform vec3 uCloudMidColor;
        uniform vec3 uCloudShadowColor;

        varying vec3 vWorldDir;

        float hash31(vec3 p) {
          p = fract(p * vec3(0.1031, 0.1030, 0.0973));
          p += dot(p, p.yxz + 33.33);
          return fract((p.x + p.y) * p.z);
        }

        float noise3D(vec3 x) {
          vec3 i = floor(x);
          vec3 f = fract(x);
          f = f * f * (3.0 - 2.0 * f);
          return mix(
            mix(
              mix(hash31(i + vec3(0.0, 0.0, 0.0)), hash31(i + vec3(1.0, 0.0, 0.0)), f.x),
              mix(hash31(i + vec3(0.0, 1.0, 0.0)), hash31(i + vec3(1.0, 1.0, 0.0)), f.x),
              f.y
            ),
            mix(
              mix(hash31(i + vec3(0.0, 0.0, 1.0)), hash31(i + vec3(1.0, 0.0, 1.0)), f.x),
              mix(hash31(i + vec3(0.0, 1.0, 1.0)), hash31(i + vec3(1.0, 1.0, 1.0)), f.x),
              f.y
            ),
            f.z
          );
        }

        // Billowy cumulus FBM for Ghibli / Shinkai cloud silhouettes
        float fbmCumulus(vec3 p) {
          float v = 0.0;
          float a = 0.52;
          vec3 shift = vec3(19.7, 31.3, 11.9);
          for (int i = 0; i < 5; i++) {
            float n = noise3D(p);
            float billow = 1.0 - abs(n * 2.0 - 1.0);
            v += a * mix(n, billow * billow, 0.55);
            p = p * 2.06 + shift;
            a *= 0.5;
          }
          return v;
        }

        void main() {
          vec3 dir = normalize(vWorldDir);
          vec3 sunDir = normalize(uSunDir);
          float elev = clamp(dir.y, -1.0, 1.0);
          float upperElev = max(elev, 0.0);

          // 1. Multi-stop Shinkai Atmospheric Vertical Gradient
          float tMid = smoothstep(0.0, 0.36, upperElev);
          float tZenith = smoothstep(0.24, 0.88, upperElev);
          vec3 skyCol = mix(uHorizonSkyColor, uMidSkyColor, tMid);
          skyCol = mix(skyCol, uZenithColor, tZenith);

          // Warm golden-peach horizon band
          float horizonBand = pow(1.0 - smoothstep(0.0, 0.28, abs(elev)), 2.2);
          skyCol = mix(skyCol, uHorizonGlowColor, horizonBand * 0.62);

          // Smooth lower hemisphere bounce (below horizon)
          if (elev < 0.0) {
            float downT = smoothstep(0.0, -0.35, elev);
            skyCol = mix(skyCol, uGroundBounceColor, downT);
          }

          // 2. Solar Mie Scattering, Corona & Crisp Anime Sun Disc
          float sunCos = clamp(dot(dir, sunDir), -1.0, 1.0);
          float mieHalo = pow(max(sunCos, 0.0), 6.0) * 0.38;
          float solarCorona = pow(max(sunCos, 0.0), 42.0) * 0.65;
          float solarDisc = smoothstep(0.9968, 0.9986, sunCos);
          skyCol += uHorizonGlowColor * mieHalo * (0.45 + 0.55 * horizonBand);
          skyCol += uSunColor * solarCorona;
          skyCol = mix(skyCol, uSunColor, solarDisc);

          // 3. Layered Procedural Cel-Shaded Cumulus & Cirrus Clouds (Upper Hemisphere)
          if (elev > -0.02) {
            float projScale = 1.0 / (max(elev, 0.0) + 0.24);
            vec3 cloudCoord = vec3(dir.x * projScale, elev * 2.4, dir.z * projScale);
            vec3 windDrift = vec3(uTime * 0.0085, 0.0, uTime * 0.0045);

            // High-altitude wispy cirrus streaks
            float cirrusMask = smoothstep(0.12, 0.32, elev) * (1.0 - smoothstep(0.62, 0.88, elev));
            if (cirrusMask > 0.001) {
              vec3 cirrusPos = cloudCoord * 1.65 + windDrift * 0.6;
              float cirrusN = fbmCumulus(vec3(cirrusPos.x * 1.8, cirrusPos.y * 0.7, cirrusPos.z * 0.65));
              float cirrusStep = smoothstep(0.58, 0.67, cirrusN) * cirrusMask * 0.42;
              skyCol = mix(skyCol, mix(uCloudMidColor, uCloudLitColor, 0.75), cirrusStep);
            }

            // Main Ghibli Cumulus Cloud Bank near horizon to mid-sky
            float bankEnvelope = smoothstep(-0.01, 0.07, elev) * (1.0 - smoothstep(0.32, 0.62, elev));
            if (bankEnvelope > 0.001) {
              vec3 pMain = cloudCoord * 1.18 + windDrift;
              float baseField = fbmCumulus(pMain);
              // Sculpt towering cumulus tops and flatter bases
              float verticalProfile = smoothstep(0.01, 0.09, elev) * (1.0 - smoothstep(0.24, 0.58, elev) * 0.48);
              float density = baseField * verticalProfile - 0.30;

              if (density > 0.0) {
                // Sample gradient toward sun & zenith for cel-shaded 3-step toon lighting
                vec3 lightStepDir = normalize(sunDir + vec3(0.0, 0.65, 0.0)) * 0.14;
                float litSample = fbmCumulus(pMain + lightStepDir);
                float shadeFactor = clamp((baseField - litSample) * 3.6 + 0.54 + elev * 0.45, 0.0, 1.0);

                // Quantize into crisp anime cel-shading bands
                float bandShadowToMid = smoothstep(0.34, 0.41, shadeFactor);
                float bandMidToLit = smoothstep(0.58, 0.65, shadeFactor);
                float silverRim = smoothstep(0.76, 0.84, shadeFactor) * (0.45 + 0.55 * pow(max(sunCos, 0.0), 3.0));

                vec3 toonCloudCol = mix(uCloudShadowColor, uCloudMidColor, bandShadowToMid);
                toonCloudCol = mix(toonCloudCol, uCloudLitColor, bandMidToLit);
                toonCloudCol = mix(toonCloudCol, uSunColor, silverRim * 0.65);

                // Subtle internal darker contour line near cloud base
                float bottomContour = 1.0 - smoothstep(0.02, 0.09, elev);
                toonCloudCol = mix(toonCloudCol, uCloudShadowColor * 0.92, bottomContour * 0.35);

                // Crisp anime silhouette edge with distance horizon fade
                float cloudAlpha = smoothstep(0.0, 0.045, density) * smoothstep(-0.01, 0.06, elev);
                skyCol = mix(skyCol, toonCloudCol, cloudAlpha * 0.95);
              }
            }
          }

          gl_FragColor = vec4(skyCol, 1.0);
        }
      `,
    });
    const animeSkyDomeMesh = new THREE.Mesh(animeSkyGeo, animeSkyMat);
    animeSkyDomeMesh.name = 'AnimeSkyDome';
    animeSkyDomeMesh.frustumCulled = false;
    animeSkyDomeMesh.renderOrder = -1000;
    scene.add(animeSkyDomeMesh);

    // Volumetric 3D Cel-Shaded Horizon Cloud Ring (GPU-instanced 112 puffs -> 1 draw call!)
    const animeCloudRingGroup = new THREE.Group();
    const cloudPuffSharedGeo = new THREE.IcosahedronGeometry(1, 2);
    const cloudToonSteps = new Uint8Array([155, 215, 255]);
    const cloudToonGradTex = new THREE.DataTexture(cloudToonSteps, 3, 1, THREE.RedFormat);
    cloudToonGradTex.minFilter = THREE.NearestFilter;
    cloudToonGradTex.magFilter = THREE.NearestFilter;
    cloudToonGradTex.needsUpdate = true;
    const cloudPuffToonMat = new THREE.MeshToonMaterial({
      color: '#ffffff',
      emissive: '#78b0e8',
      emissiveIntensity: 0.34,
      gradientMap: cloudToonGradTex,
      fog: false,
      depthWrite: false,
    });
    const cloudClusterCount = 16;
    const cloudPuffSpecs: Array<[number, number, number, number, number, number]> = [
      [0, 0, 0, 34, 21, 18],
      [-24, -4, 3, 25, 16, 15],
      [25, -3, 2, 26, 17, 15],
      [-11, 10, -2, 24, 18, 16],
      [12, 11, -1, 23, 17, 15],
      [-38, -9, 5, 17, 11, 12],
      [39, -8, 4, 18, 12, 12],
    ];
    const cloudPuffMatrices: THREE.Matrix4[] = [];
    const cloudClusterHelper = new THREE.Object3D();
    const cloudPuffLocalMat = new THREE.Matrix4();
    const cloudPuffPosTmp = new THREE.Vector3();
    const cloudPuffQuatIdent = new THREE.Quaternion();
    const cloudPuffScaleTmp = new THREE.Vector3();
    for (let c = 0; c < cloudClusterCount; c++) {
      const angle = (c / cloudClusterCount) * Math.PI * 2 + (c % 2 === 0 ? 0.08 : -0.06);
      const dist = 420 + (c % 3) * 35;
      const heightY = 48 + (c % 4) * 18;
      cloudClusterHelper.position.set(Math.cos(angle) * dist, heightY, Math.sin(angle) * dist);
      cloudClusterHelper.lookAt(0, heightY * 0.85, 0);
      const clusterScale = 0.85 + (c % 3) * 0.22;
      cloudClusterHelper.scale.setScalar(clusterScale);
      cloudClusterHelper.updateMatrix();
      for (const [px, py, pz, sx, sy, sz] of cloudPuffSpecs) {
        cloudPuffPosTmp.set(px, py, pz);
        cloudPuffScaleTmp.set(sx, sy, sz);
        cloudPuffLocalMat.compose(cloudPuffPosTmp, cloudPuffQuatIdent, cloudPuffScaleTmp);
        cloudPuffMatrices.push(new THREE.Matrix4().multiplyMatrices(cloudClusterHelper.matrix, cloudPuffLocalMat));
      }
    }
    const cloudRingBatch = createInstancedMeshWithOutline({
      geometry: cloudPuffSharedGeo,
      material: cloudPuffToonMat,
      matrices: cloudPuffMatrices,
      name: 'AnimeHorizonCloudRingInstanced',
      renderOrder: -999,
      padding: 4.0,
      lockStaticMatrix: true,
    });
    animeCloudRingGroup.add(cloudRingBatch.mesh);
    scene.add(animeCloudRingGroup);

    // Floating 4-Point Anime Star Sparkles Particle System
    const sparkleCanvas = document.createElement('canvas');
    sparkleCanvas.width = 64;
    sparkleCanvas.height = 64;
    const spCtx = sparkleCanvas.getContext('2d');
    if (spCtx) {
      const grad = spCtx.createRadialGradient(32, 32, 1, 32, 32, 28);
      grad.addColorStop(0, 'rgba(255, 255, 255, 1.0)');
      grad.addColorStop(0.25, 'rgba(235, 248, 255, 0.85)');
      grad.addColorStop(0.6, 'rgba(165, 225, 255, 0.22)');
      grad.addColorStop(1, 'rgba(165, 225, 255, 0.0)');
      spCtx.fillStyle = grad;
      spCtx.fillRect(0, 0, 64, 64);
      // Crisp 4-point anime star cross
      spCtx.fillStyle = 'rgba(255, 255, 255, 0.95)';
      spCtx.beginPath();
      spCtx.moveTo(32, 2);
      spCtx.quadraticCurveTo(34, 29, 62, 32);
      spCtx.quadraticCurveTo(34, 35, 32, 62);
      spCtx.quadraticCurveTo(30, 35, 2, 32);
      spCtx.quadraticCurveTo(30, 29, 32, 2);
      spCtx.closePath();
      spCtx.fill();
    }
    const animeSparkleTex = new THREE.CanvasTexture(sparkleCanvas);
    animeSparkleTex.needsUpdate = true;

    const sparkleCount = 95;
    const sparkleGeo = new THREE.BufferGeometry();
    const sparklePositions = new Float32Array(sparkleCount * 3);
    for (let s = 0; s < sparkleCount; s++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 0.68 + 0.22); // upper sky hemisphere
      const rad = 360 + Math.random() * 80;
      sparklePositions[s * 3] = rad * Math.sin(phi) * Math.cos(theta);
      sparklePositions[s * 3 + 1] = rad * Math.cos(phi);
      sparklePositions[s * 3 + 2] = rad * Math.sin(phi) * Math.sin(theta);
    }
    sparkleGeo.setAttribute('position', new THREE.BufferAttribute(sparklePositions, 3));
    const animeSparkleMat = new THREE.PointsMaterial({
      color: 0xffffff,
      map: animeSparkleTex,
      alphaMap: animeSparkleTex,
      size: 9.5,
      transparent: true,
      opacity: 0.82,
      depthWrite: false,
      fog: false,
      blending: THREE.AdditiveBlending,
    });
    const animeSparklePoints = new THREE.Points(sparkleGeo, animeSparkleMat);
    animeSparklePoints.name = 'AnimeSkySparkles';
    animeSparklePoints.frustumCulled = false;
    animeSparklePoints.renderOrder = -998;
    scene.add(animeSparklePoints);

    const initialCamAspect =
      (container.clientWidth || window.innerWidth) /
      Math.max(1, container.clientHeight || window.innerHeight);
    const camera = new THREE.PerspectiveCamera(
      computeAdaptiveWorldCameraFov(BUDDIES_CONSTANTS.camera.fov, initialCamAspect),
      initialCamAspect,
      BUDDIES_CONSTANTS.camera.near,
      initialHorizonFog.cameraFar,
    );

    // Post-processing chain engaged only while inside a house (visit + edit
    // modes): ground-truth ambient occlusion grounds the furniture, a whisper
    // of bloom lifts the lamps and signs, SMAA cleans the edges, and the
    // output pass applies tone mapping + sRGB. The open world keeps the
    // plain renderer path, so its look and cost are unchanged.
    // The house interior renders with the SAME plain pipeline as the plaza
    // (no post-processing chain): the GTAO/bloom/SMAA composer that used to
    // run only indoors halved the frame rate on mobile GPUs, so it was
    // removed at the user's request — interiors now match the plaza style.


    const hemiLight = new THREE.HemisphereLight('#f8f7ee', '#987e60', 1.12);
    scene.add(hemiLight);

    // Bundled Blitz Sun Spherical Angles: phi = 0.63, theta = 0.72, radius = 50 -> warm coastal sunlit gold (#ffe9bc)
    const blitzSunOffset = getBlitzDefaultLightDirection().multiplyScalar(52);
    const dirLight = new THREE.DirectionalLight('#ffe9bc', 2.18);
    dirLight.position.copy(blitzSunOffset);
    dirLight.castShadow = initialGraphicsProfile.shadowsEnabled;
    let shadowMapRes: AdaptiveShadowMapRes = initialGraphicsProfile.shadowMapRes;
    dirLight.shadow.mapSize.set(shadowMapRes, shadowMapRes);
    const d = 36;
    let shadowTexelWorldSize = (d * 2) / shadowMapRes;
    let shadowResCooldownFrames = 0;
    let activeFoliageShadowsEnabled = initialGraphicsProfile.foliageShadowsEnabled;
    let activeHudBlurEnabled = initialGraphicsProfile.hudBackdropBlurEnabled;
    if (typeof document !== 'undefined') {
      document.documentElement.classList.toggle('hud-blur-lite', !activeHudBlurEnabled);
    }
    let lastShadowHalfSpan = d;
    let lastShadowFar = 122;
    const shadowLightBack = blitzSunOffset.clone().normalize();
    const shadowLightRight = new THREE.Vector3()
      .crossVectors(new THREE.Vector3(0, 1, 0), shadowLightBack)
      .normalize();
    const shadowLightUp = new THREE.Vector3()
      .crossVectors(shadowLightBack, shadowLightRight)
      .normalize();
    dirLight.shadow.camera.near = 2;
    const syncDirShadowCameraEnvelope = (halfSpan: number, far: number, force = false) => {
      lastShadowHalfSpan = halfSpan;
      lastShadowFar = far;
      if (
        !force &&
        Math.abs(dirLight.shadow.camera.right - halfSpan) <= 0.5 &&
        Math.abs(dirLight.shadow.camera.far - far) <= 1
      ) {
        return;
      }
      dirLight.shadow.camera.left = -halfSpan;
      dirLight.shadow.camera.right = halfSpan;
      dirLight.shadow.camera.top = halfSpan;
      dirLight.shadow.camera.bottom = -halfSpan;
      dirLight.shadow.camera.far = far;
      const texelWorld = (halfSpan * 2) / shadowMapRes;
      const depthSpan = Math.max(1, far - dirLight.shadow.camera.near);
      // Scale normalBias proportionally to shadow texel width (~1.65x texel) and depth bias to ~0.035m
      // so newly shadow-receiving wooden roofs, facades, and curved tree trunks render soft dappled
      // leaf shadows with zero shadow acne / striping and zero peter-panning across all camera views.
      dirLight.shadow.normalBias = Math.min(0.28, Math.max(0.052, texelWorld * 1.65));
      dirLight.shadow.bias = -Math.min(0.0005, (0.030 + texelWorld * 0.16) / depthSpan);
      dirLight.shadow.radius = isSoftwareGl ? 1.0 : halfSpan > 100 ? 1.5 : 1.85;
      dirLight.shadow.camera.updateProjectionMatrix();
    };
    syncDirShadowCameraEnvelope(d, 122, true);
    dirLight.shadow.intensity = 0.9;
    let prevSnappedShadowX = Number.NaN;
    let prevSnappedShadowZ = Number.NaN;
    let lastShadowUpdateFrame = -999;
    scene.add(dirLight);
    scene.add(dirLight.target);

    let windUniformsRef: BlitzWindUniforms | null = null;
    const weatherSystem = buildDynamicWeatherSystem3D({
      scene,
      hemiLight,
      dirLight,
      animeSkyUniforms,
      cloudPuffToonMat,
      animeSparkleMat,
      isSoftwareGl,
      initialPreset: lightingPresetRef.current,
    });
    const applyLightingPreset = (presetKey: LightingPresetKey) => {
      weatherSystem.syncExternalPresetProp(presetKey, windUniformsRef);
    };
    applyLightingRef.current = applyLightingPreset;
    weatherSystem.syncExternalPresetProp(lightingPresetRef.current, null);

    const applyFovMode = (mode: 'webgl35' | 'ortho18') => {
      const baseFov =
        mode === 'ortho18'
          ? BUDDIES_CONSTANTS.camera.pseudoOrthoFov
          : BUDDIES_CONSTANTS.camera.fov;
      camera.fov = computeAdaptiveWorldCameraFov(baseFov, camera.aspect || 1.6);
      camera.updateProjectionMatrix();
    };
    applyFovModeRef.current = applyFovMode;

    // 3. Cel-Shaded Materials & Hard Black Ink Outlines (#17110f)
    const toonSteps = new Uint8Array([105, 200, 255]);
    const toonGradientMap = new THREE.DataTexture(toonSteps, 3, 1, THREE.RedFormat);
    toonGradientMap.minFilter = THREE.NearestFilter;
    toonGradientMap.magFilter = THREE.NearestFilter;
    toonGradientMap.needsUpdate = true;

    const makeToonMat = (hex: number | string) =>
      new THREE.MeshToonMaterial({
        color: hex,
        gradientMap: toonGradientMap,
      });

    const inkOutlineMat = new THREE.MeshBasicMaterial({
      color: 0x12121e,
      side: THREE.BackSide,
      fog: true,
    });
    const flashWhiteMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
    const frozenIceMat = makeToonMat(0x80e5ff);

    const matRedCrate = makeToonMat('#ff3b30');
    const matSuperCrate = makeToonMat('#00d2ff');
    const matLegendCrate = makeToonMat('#ffd700');
    const matSilverMetallicCrate = new THREE.MeshStandardMaterial({
      color: 0xe2e8f0,
      metalness: 0.92,
      roughness: 0.14,
      emissive: 0x38bdf8,
      emissiveIntensity: 0.18,
    });
    const matGoldMetallicCrate = new THREE.MeshStandardMaterial({
      color: 0xfbbf24,
      metalness: 0.94,
      roughness: 0.12,
      emissive: 0xf59e0b,
      emissiveIntensity: 0.24,
    });
    const getCrateFallbackMaterial = (kind: WorldCrateKind): THREE.Material =>
      kind === 'medical'
        ? matWhite
        : kind === 'gold_metallic'
          ? matGoldMetallicCrate
          : kind === 'silver_metallic'
            ? matSilverMetallicCrate
            : kind === 'legend'
              ? matLegendCrate
              : kind === 'super'
                ? matSuperCrate
                : matRedCrate;
    const matBlueTeam = makeToonMat('#2979ff');
    const matRedTeam = makeToonMat('#ff3b30');
    const matTankHighlight = makeToonMat('#b8ff3c');
    const matYellow = makeToonMat('#ffbe18');
    const matDarkSteel = makeToonMat('#222533');
    const matWhite = makeToonMat('#faf7f5');
    const matSkin = makeToonMat('#ffd19a');

    const addOutlinedPart = (
      parent: THREE.Object3D,
      geo: THREE.BufferGeometry,
      mat: THREE.Material,
      pos: [number, number, number],
      rot: [number, number, number] = [0, 0, 0],
      outlineScale = 1.08,
      castShadow = true,
    ): THREE.Mesh => {
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(pos[0], pos[1], pos[2]);
      mesh.rotation.set(rot[0], rot[1], rot[2]);
      mesh.frustumCulled = true;
      mesh.castShadow = castShadow;
      mesh.receiveShadow = true;
      mesh.userData.baseMaterial = mat;

      const outline = new THREE.Mesh(geo, inkOutlineMat);
      outline.scale.setScalar(outlineScale);
      outline.frustumCulled = true;
      mesh.add(outline);

      parent.add(mesh);
      return mesh;
    };

    const shadowDiscGeo = new THREE.CircleGeometry(1.1, 24);
    shadowDiscGeo.rotateX(-Math.PI / 2);
    const shadowDiscMat = new THREE.MeshBasicMaterial({
      color: 0x12121e,
      transparent: true,
      opacity: 0.0,
      visible: false,
      depthWrite: false,
    });

    const avatarShadowCanvas = document.createElement('canvas');
    avatarShadowCanvas.width = 64;
    avatarShadowCanvas.height = 64;
    const avatarShadowCtx = avatarShadowCanvas.getContext('2d');
    if (avatarShadowCtx) {
      const grad = avatarShadowCtx.createRadialGradient(32, 32, 3, 32, 32, 30);
      grad.addColorStop(0.0, 'rgba(10, 15, 28, 0.56)');
      grad.addColorStop(0.45, 'rgba(10, 15, 28, 0.36)');
      grad.addColorStop(0.78, 'rgba(10, 15, 28, 0.12)');
      grad.addColorStop(1.0, 'rgba(10, 15, 28, 0.0)');
      avatarShadowCtx.fillStyle = grad;
      avatarShadowCtx.fillRect(0, 0, 64, 64);
    }
    const avatarShadowTex = new THREE.CanvasTexture(avatarShadowCanvas);
    const avatarContactShadowMat = new THREE.MeshBasicMaterial({
      map: avatarShadowTex,
      transparent: true,
      opacity: 1.0,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -1,
    });

    // =========================================================================
    // 4. CURVED PLANET ENVIRONMENT, PONDS, FLORA & SKY SUNBEAMS
    // =========================================================================
    const windUniforms: BlitzWindUniforms = {
      uTime: { value: 0 },
      uWindPhase: { value: 0 },
      uWindDirection: { value: new THREE.Vector2(0.7071, 0.7071) },
      uWindStrength: { value: 0.32 },
      uWindGust: { value: 0.0 },
      uLightDirection: { value: getBlitzDefaultLightDirection() },
      uLightColor: { value: new THREE.Color('#fff2c8') },
      uShadowColor: { value: new THREE.Color('#4e6752') },
      uPlanetPivot: { value: new THREE.Vector3(0, 0, 12.5) },
      uCurvatureStrength: { value: PLANET_CURVATURE_STRENGTH },
      uDirShadowMapSize: { value: shadowMapRes },
    };
    windUniformsRef = windUniforms;
    applyLightingPreset(lightingPresetRef.current);

    // Pre-bake 1024x1024 GPU terrain acceleration LUT once (~2ms) so ground & grass shaders
    // skip ~150 lines of SDF math on ~80% of pixels/vertices with zero visual compromise.
    const terrainAccelBake = bakeBlitzTerrainAccelTexture(
      renderer,
      windUniforms,
      isSoftwareGl ? 512 : 1024,
    );
    const curvedPlanetEnv = createCurvedPlanetEnvironment(scene, windUniforms, isSoftwareGl);
    const underwaterEcology = buildUnderwaterEcology3D(scene, windUniforms, isSoftwareGl);

    // 4A. Modern Urban Street Tram (100% Low-Floor LRV — 1 Rangkaian 2 Gerbong) circulating the road network
    const cityTram = createProceduralCityTramConsist(scene, windUniforms, isSoftwareGl);
    let cityTramDistance = 328.0; // Starts entering the South Collector Road curve right in front of Blue Base!
    let cityTramCurrentSpeedMps: number = CITY_TRAM_SPEC.cruiseSpeed;
    let plazaTrafficSignalState: PlazaTrafficSignalState = createInitialPlazaTrafficSignalState();
    let eastTrafficSignalState: PlazaTrafficSignalState = createInitialPlazaTrafficSignalState(
      'tram_green',
      8.0,
    );
    cityTram.update(cityTramDistance, 0, 0, 0, 0);

    // 4A-1. 60 FPS GPU-Instanced 4-Tier City Illumination & Autonomous Signal-Compliant Traffic Fleet
    const cityLightingAndTraffic = buildCityLightingAndTrafficSystem(
      scene,
      windUniforms,
      isSoftwareGl,
    );

    // 4A-2. Compact Floating Seat Discs above Plaza, Park, Casino & Beach Seats (unified with Cafe chair triggers)
    const lobbySeatCoinResourceCache: CompactSeatCoinResourceCache = new Map();
    const lobbySeatCoinMeshes = LOBBY_SEAT_SPOTS.map((spot) => {
      const { coinRoot, blueCoin, greenCoin } = buildCompactSeatIndicatorPair(
        1.65,
        lobbySeatCoinResourceCache,
      );
      coinRoot.position.set(spot.x, 2.0, spot.z);
      coinRoot.visible = false;
      scene.add(coinRoot);
      return { coinRoot, blueCoin, greenCoin };
    });

    // Drop Zone Circles removed ("oh ya drop box itu random di area warzone hapus saja lingkaran dropzone itu")
    const buildDropZonePad = (x: number, z: number, _colorMat: THREE.Material) => {
      const g = new THREE.Group();
      g.position.set(x, 0.06, z);
      g.visible = false;
      return g;
    };
    const centerDropZoneGroup = buildDropZonePad(0, 0, matRedCrate);
    const westSuperDropZoneGroup = buildDropZonePad(-53.5, 0.0, matSuperCrate);
    const eastSuperDropZoneGroup = buildDropZonePad(60.0, 0.0, matSuperCrate);

    // 4A-2. Dynamic Supply Drop Ground Beacon Ring (Central Oasis & Harbor Dock)
    const supplyDropBeaconGroup = new THREE.Group();
    const supplyBeaconOuterRingGeo = new THREE.RingGeometry(3.4, 4.1, 36);
    supplyBeaconOuterRingGeo.rotateX(-Math.PI / 2);
    const supplyBeaconOuterRingMat = new THREE.MeshBasicMaterial({
      color: 0xfacc15,
      transparent: true,
      opacity: 0.85,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    const supplyBeaconOuterRing = new THREE.Mesh(supplyBeaconOuterRingGeo, supplyBeaconOuterRingMat);
    supplyDropBeaconGroup.add(supplyBeaconOuterRing);

    const supplyBeaconInnerDiscGeo = new THREE.RingGeometry(1.1, 1.55, 28);
    supplyBeaconInnerDiscGeo.rotateX(-Math.PI / 2);
    const supplyBeaconInnerDiscMat = new THREE.MeshBasicMaterial({
      color: 0x38bdf8,
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    const supplyBeaconInnerRing = new THREE.Mesh(supplyBeaconInnerDiscGeo, supplyBeaconInnerDiscMat);
    supplyDropBeaconGroup.add(supplyBeaconInnerRing);

    const supplyBeaconBeamGeo = new THREE.CylinderGeometry(0.32, 1.25, 16.0, 16, 1, true);
    const supplyBeaconBeamMat = new THREE.MeshBasicMaterial({
      color: 0xfef08a,
      transparent: true,
      opacity: 0.26,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    const supplyBeaconBeam = new THREE.Mesh(supplyBeaconBeamGeo, supplyBeaconBeamMat);
    supplyBeaconBeam.position.y = 8.0;
    supplyDropBeaconGroup.add(supplyBeaconBeam);
    supplyDropBeaconGroup.visible = false;
    scene.add(supplyDropBeaconGroup);

    // =========================================================================
    // 4B. CURVED PLANET INFINITE GRASS + FLOATING DANDELION SEEDS SHADER
    // =========================================================================
    const blitzGrassSystem = createBlitzInfiniteGrassSystem(scene, windUniforms, isSoftwareGl);
    let loadedBlitzAssets: LoadedBlitzAssets | null = getCachedLoadedBlitzAssets();
    const realPropsGroup = new THREE.Group();
    realPropsGroup.name = 'RealBlitzFactoryProps';
    scene.add(realPropsGroup);

    // 3D Map Editor Placement Cursor Ring on Ground
    const editorCursorGroup = new THREE.Group();
    editorCursorGroup.name = 'MapEditorCursor';
    editorCursorGroup.visible = playModeRef.current === 'editor';
    const cursorOuterRing = new THREE.Mesh(
      new THREE.RingGeometry(1.4, 1.85, 28),
      new THREE.MeshBasicMaterial({ color: 0xb4ff39, side: THREE.DoubleSide }),
    );
    cursorOuterRing.rotation.x = -Math.PI / 2;
    cursorOuterRing.position.y = 0.12;
    editorCursorGroup.add(cursorOuterRing);

    const cursorDirArrow = new THREE.Mesh(
      new THREE.BoxGeometry(0.35, 0.18, 1.9),
      new THREE.MeshBasicMaterial({ color: 0x00d2ff }),
    );
    cursorDirArrow.position.set(0, 0.16, 0.95);
    editorCursorGroup.add(cursorDirArrow);
    scene.add(editorCursorGroup);

    // =========================================================================
    // 5. TWO 1:1 SYMMETRIC 4-PLOT BASE COMPLEXES (BLUE SOUTH vs RED NORTH)
    //    + COMPACT 4-COLUMN (2x2) STACKING PAD IN EACH INDIVIDUAL BASE PLOT
    // =========================================================================
    // Shared sculpted geometries for all Commander & Public Stacking Pads
    const padDeckGeo = (() => {
      const hs = STACKING_PAD_SPEC.deckHalfSize;
      const ch = STACKING_PAD_SPEC.deckChamfer;
      const shape = new THREE.Shape();
      shape.moveTo(-hs + ch, -hs);
      shape.lineTo(hs - ch, -hs);
      shape.lineTo(hs, -hs + ch);
      shape.lineTo(hs, hs - ch);
      shape.lineTo(hs - ch, hs);
      shape.lineTo(-hs + ch, hs);
      shape.lineTo(-hs, hs - ch);
      shape.lineTo(-hs, -hs + ch);
      shape.closePath();
      const geo = new THREE.ExtrudeGeometry(shape, {
        depth: STACKING_PAD_SPEC.deckHeight - 0.02,
        bevelEnabled: true,
        bevelThickness: 0.02,
        bevelSize: 0.02,
        bevelSegments: 1,
      });
      geo.rotateX(-Math.PI / 2);
      geo.computeBoundingBox();
      if (geo.boundingBox) {
        geo.translate(0, -geo.boundingBox.min.y, 0);
      }
      return geo;
    })();

    const padChevronGeo = (() => {
      const pts = getStackingPadChevronOutlinePoints();
      const shape = new THREE.Shape();
      pts.forEach(([x, y], idx) => {
        if (idx === 0) shape.moveTo(x, y);
        else shape.lineTo(x, y);
      });
      shape.closePath();
      const geo = new THREE.ExtrudeGeometry(shape, {
        depth: 0.022,
        bevelEnabled: false,
      });
      geo.rotateX(-Math.PI / 2);
      geo.computeBoundingBox();
      if (geo.boundingBox) {
        geo.translate(0, -geo.boundingBox.min.y, 0);
      }
      return geo;
    })();

    const matPadRecess = makeToonMat('#12151e');
    const padSocketGeo = new THREE.BoxGeometry(
      STACKING_PAD_SPEC.socketSize,
      STACKING_PAD_SPEC.socketHeight,
      STACKING_PAD_SPEC.socketSize,
    );
    const padTileGeo = new THREE.BoxGeometry(
      STACKING_PAD_SPEC.bayTileSize,
      STACKING_PAD_SPEC.bayTileHeight,
      STACKING_PAD_SPEC.bayTileSize,
    );
    const padRailHGeo = new THREE.BoxGeometry(2.55, 0.08, 0.11);
    const padRailVGeo = new THREE.BoxGeometry(0.11, 0.08, 2.55);
    const padPylonBodyGeo = new THREE.CylinderGeometry(0.11, 0.16, 0.32, 6);
    const padPylonCapGeo = new THREE.CylinderGeometry(0.085, 0.105, 0.075, 6);

    const buildCompositeStackingPadBase = (
      padStaticGroup: THREE.Group,
      teamMat: THREE.Material,
    ): [number, number][] => {
      const o = STACKING_PAD_SPEC.bayOffset;
      const tileOffsets: [number, number][] = [
        [-o, -o],
        [o, -o],
        [-o, o],
        [o, o],
      ];

      addOutlinedPart(padStaticGroup, padDeckGeo, matDarkSteel, [0, 0, 0], [0, 0, 0], 1.03, false);

      const bayTileCenterY = STACKING_PAD_SPEC.bayTopY - STACKING_PAD_SPEC.bayTileHeight * 0.5;
      tileOffsets.forEach(([tx, tz]) => {
        const socketMesh = new THREE.Mesh(padSocketGeo, matPadRecess);
        socketMesh.position.set(tx, 0.205, tz);
        socketMesh.receiveShadow = true;
        padStaticGroup.add(socketMesh);

        const tileMesh = new THREE.Mesh(padTileGeo, teamMat);
        tileMesh.position.set(tx, bayTileCenterY, tz);
        tileMesh.receiveShadow = true;
        padStaticGroup.add(tileMesh);

        const chevronMesh = new THREE.Mesh(padChevronGeo, matWhite);
        chevronMesh.position.set(tx, STACKING_PAD_SPEC.bayTopY + 0.001, tz);
        chevronMesh.receiveShadow = true;
        padStaticGroup.add(chevronMesh);
      });

      // Perimeter safety rails
      addOutlinedPart(padStaticGroup, padRailHGeo, matPadRecess, [0, 0.22, -2.06], [0, 0, 0], 1.06, false);
      addOutlinedPart(padStaticGroup, padRailHGeo, matPadRecess, [0, 0.22, 2.06], [0, 0, 0], 1.06, false);
      addOutlinedPart(padStaticGroup, padRailVGeo, matPadRecess, [-2.06, 0.22, 0], [0, 0, 0], 1.06, false);
      addOutlinedPart(padStaticGroup, padRailVGeo, matPadRecess, [2.06, 0.22, 0], [0, 0, 0], 1.06, false);

      // Four corner armored emitter pylons
      const po = STACKING_PAD_SPEC.pylonOffset;
      const pylonCorners: [number, number][] = [
        [-po, -po],
        [po, -po],
        [-po, po],
        [po, po],
      ];
      pylonCorners.forEach(([px, pz]) => {
        addOutlinedPart(padStaticGroup, padPylonBodyGeo, matDarkSteel, [px, 0.34, pz], [0, 0, 0], 1.08, false);
        addOutlinedPart(padStaticGroup, padPylonCapGeo, teamMat, [px, 0.535, pz], [0, 0, 0], 1.08, false);
      });

      return tileOffsets;
    };

    const buildSingleStackingPadMesh = (
      team: 'blue' | 'red',
      padX: number,
      padZ: number,
      commanderIdx: number,
    ) => {
      const isModelEstate = team === 'blue' && commanderIdx === 0;
      const teamMat = team === 'blue' ? matBlueTeam : matRedTeam;
      const baseYaw = team === 'blue' ? 0 : Math.PI;
      const padGroup = new THREE.Group();
      padGroup.position.set(padX, 0.04, padZ);
      padGroup.rotation.y = baseYaw;
      padGroup.visible = true;
      scene.add(padGroup);

      // Composite 4-Column (2x2) Industrial Stacking Pad — visible when plot is Model Estate or Claimed via NEAR Gamepass
      const padStaticGroup = new THREE.Group();
      padStaticGroup.visible = isModelEstate;
      padGroup.add(padStaticGroup);
      const tileOffsets = buildCompositeStackingPadBase(padStaticGroup, teamMat);
      bakeStaticGroupMeshes(padStaticGroup);

      // Self-Service Tactical Kiosk placed on ALL 8 Base Plots (1 Model Estate + 7 Empty Grass Plots) at identical local coordinates!
      const kioskMesh = buildSelfServiceTacticalKioskMesh(windUniforms, isSoftwareGl);
      kioskMesh.position.set(1.22, 0.0, -6.48);
      kioskMesh.rotation.y = -Math.PI / 2;
      kioskMesh.visible = true;
      const plotKioskChevron = buildCompactInteractiveChevronMarker(0.13, 0.25, '#38bdf8');
      plotKioskChevron.group.position.set(0, 2.92, 0.02);
      kioskMesh.add(plotKioskChevron.group);
      kioskMesh.userData.interactiveChevron = plotKioskChevron;
      padGroup.add(kioskMesh);
      padGroup.updateMatrixWorld(true);

      const mergedCage = new THREE.LineSegments(
        new THREE.EdgesGeometry(new THREE.BoxGeometry(3.85, 2.95, 3.85)),
        new THREE.LineBasicMaterial({ color: 0xb4ff39, transparent: true, opacity: 0.78 }),
      );
      mergedCage.position.set(0, 1.65, 0);
      mergedCage.visible = false;
      padGroup.add(mergedCage);

      const ghostPatternBox = new THREE.LineSegments(
        new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1)),
        new THREE.LineBasicMaterial({
          color: 0x00d2ff,
          transparent: true,
          opacity: 0.85,
        }),
      );
      ghostPatternBox.visible = isModelEstate;
      padGroup.add(ghostPatternBox);

      const slotMeshes: THREE.Group[] = [];
      const ghostSlotMeshes: THREE.LineSegments[] = [];
      const slotGeo = new THREE.BoxGeometry(
        UNIFIED_WORLD_CRATE_SIZE,
        UNIFIED_WORLD_CRATE_SIZE,
        UNIFIED_WORLD_CRATE_SIZE,
      );
      const ghostSlotGeo = new THREE.BoxGeometry(
        UNIFIED_WORLD_CRATE_SIZE,
        UNIFIED_WORLD_CRATE_SIZE,
        UNIFIED_WORLD_CRATE_SIZE,
      );
      const ghostSlotEdgesGeo = new THREE.EdgesGeometry(ghostSlotGeo);
      const ghostCoreGeo = new THREE.BoxGeometry(
        UNIFIED_WORLD_CRATE_SIZE - 0.08,
        UNIFIED_WORLD_CRATE_SIZE - 0.08,
        UNIFIED_WORLD_CRATE_SIZE - 0.08,
      );

      for (let i = 0; i < 8; i++) {
        const layer = i < 4 ? 0 : 1;
        const [tx, tz] = tileOffsets[i % 4];
        const slotY = computeStackingPadSlotY(layer);
        const slotGrp = new THREE.Group();
        slotGrp.position.set(tx, slotY, tz);
        slotGrp.visible = false;
        addOutlinedPart(slotGrp, slotGeo, matRedCrate, [0, 0, 0], [0, 0, 0], 1.07, true);
        populateRealBlitzCrateBoxFromGlb(
          slotGrp,
          'red',
          loadedBlitzAssets,
          windUniforms,
          isSoftwareGl,
          UNIFIED_WORLD_CRATE_SIZE,
        );
        padGroup.add(slotGrp);
        slotMeshes.push(slotGrp);

        const slotWireMat = new THREE.LineBasicMaterial({
          color: 0xff4d3d,
          transparent: true,
          opacity: 0.9,
        });
        const slotCoreMat = new THREE.MeshBasicMaterial({
          color: 0xff4d3d,
          transparent: true,
          opacity: 0.18,
          depthWrite: false,
        });
        const gm = new THREE.LineSegments(ghostSlotEdgesGeo, slotWireMat);
        gm.position.set(tx, slotY, tz);
        gm.visible = false;
        const coreMesh = new THREE.Mesh(ghostCoreGeo, slotCoreMat);
        gm.add(coreMesh);
        gm.userData.coreMat = slotCoreMat;
        padGroup.add(gm);
        ghostSlotMeshes.push(gm);
      }

      const padSign = createBillboardSign(5.4, 1.35);
      padSign.sprite.position.set(0, 4.5, 0);
      padSign.sprite.visible = false;

      const kioskHoloSign = createBillboardSign(3.6, 0.98);
      kioskHoloSign.sprite.position.set(-0.65, 4.35, 0.28);
      kioskHoloSign.sprite.visible = false;

      return {
        commanderIdx,
        padGroup,
        padStaticGroup,
        kioskMesh,
        kioskHoloSign,
        padX,
        padZ,
        worldX: padX,
        worldZ: padZ,
        slotMeshes,
        ghostSlotMeshes,
        ghostPatternBox,
        mergedCage,
        padSign,
      };
    };

    const buildBaseHqAndPad = (team: 'blue' | 'red', hqX: number, hqZ: number, _padX: number, _padZ: number) => {
      const sign = team === 'blue' ? 1 : -1;
      const baseYaw = team === 'blue' ? Math.PI / 2 : -Math.PI / 2;
      const baseGroup = new THREE.Group();
      baseGroup.position.set(hqX, 0, hqZ);
      baseGroup.rotation.y = baseYaw;
      scene.add(baseGroup);

      buildMilitaryBaseMasterplan(baseGroup, team, windUniforms, isSoftwareGl);

      const hpSign = createBillboardSign(5.5, 1.35);
      hpSign.sprite.position.set(-1.8, 8.8, -1.2);
      hpSign.sprite.visible = false;

      // Build 4 Compact 2x2 Stacking Pads (Pad P1..P4) flush against the right fence (relZ = +7.3) of the 4 Individual Base Plots at x = sign * [-37.7, -7.7, +22.3, +52.3], z = sign * 77.8
      const padOffsetsX = [-37.7, -7.7, 22.3, 52.3];
      const commanderPads = padOffsetsX.map((ox, idx) =>
        buildSingleStackingPadMesh(team, hqX + sign * ox, hqZ - sign * 8.2, idx),
      );
      const primaryPad = commanderPads[0];

      return {
        baseGroup,
        hpSign,
        commanderPads,
        padGroup: primaryPad.padGroup,
        kioskMesh: primaryPad.kioskMesh,
        hqX,
        hqZ,
        padX: primaryPad.padX,
        padZ: primaryPad.padZ,
        slotMeshes: primaryPad.slotMeshes,
        ghostSlotMeshes: primaryPad.ghostSlotMeshes,
        ghostPatternBox: primaryPad.ghostPatternBox,
        mergedCage: primaryPad.mergedCage,
        padSign: primaryPad.padSign,
      };
    };

    const blueBase = buildBaseHqAndPad('blue', 0.0, 86.0, -37.7, 77.8);
    const redBase = buildBaseHqAndPad('red', 0.0, -86.0, 37.7, -77.8);

    // 5B. 8 SHIELDED PUBLIC WARZONE CRATE PADS (4 BLUE SOUTH + 4 RED NORTH ON GRASS ISLAND CORNERS, TANPA KIOSK)
    const buildPublicWarzoneCratePadMesh = (spec: (typeof PUBLIC_WARZONE_CRATE_PADS)[number]) => {
      const teamMat = spec.teamBias === 'blue' ? matBlueTeam : matRedTeam;
      const shieldColorHex = spec.teamBias === 'blue' ? 0x38bdf8 : 0xff453a;
      const shieldRadius = spec.shieldRadius ?? PUBLIC_PAD_SHIELD_RADIUS;
      const padGroup = new THREE.Group();
      padGroup.position.set(spec.x, 0.04, spec.z);
      scene.add(padGroup);

      const padStaticGroup = new THREE.Group();
      padGroup.add(padStaticGroup);
      const tileOffsets = buildCompositeStackingPadBase(padStaticGroup, teamMat);
      bakeStaticGroupMeshes(padStaticGroup);

      // Safe Shield Floor Ring & Thin Cylindrical Light Curtain (100% on Grass Island Corner)
      const shieldFloorRingGeo = new THREE.RingGeometry(shieldRadius - 0.22, shieldRadius, 48);
      shieldFloorRingGeo.rotateX(-Math.PI / 2);
      const shieldFloorRingMat = new THREE.MeshBasicMaterial({
        color: shieldColorHex,
        transparent: true,
        opacity: 0.82,
        side: THREE.DoubleSide,
        depthWrite: false,
      });
      const shieldFloorRing = new THREE.Mesh(shieldFloorRingGeo, shieldFloorRingMat);
      shieldFloorRing.position.y = 0.03;
      padGroup.add(shieldFloorRing);

      const shieldInnerDiscGeo = new THREE.CircleGeometry(shieldRadius - 0.22, 48);
      shieldInnerDiscGeo.rotateX(-Math.PI / 2);
      const shieldInnerDiscMat = new THREE.MeshBasicMaterial({
        color: shieldColorHex,
        transparent: true,
        opacity: 0.12,
        side: THREE.DoubleSide,
        depthWrite: false,
      });
      const shieldInnerDisc = new THREE.Mesh(shieldInnerDiscGeo, shieldInnerDiscMat);
      shieldInnerDisc.position.y = 0.02;
      padGroup.add(shieldInnerDisc);

      const shieldCurtainHeight = 2.9;
      const shieldCurtainGeo = new THREE.CylinderGeometry(
        shieldRadius,
        shieldRadius,
        shieldCurtainHeight,
        48,
        1,
        true,
      );
      const shieldCurtainMat = new THREE.MeshBasicMaterial({
        color: shieldColorHex,
        transparent: true,
        opacity: 0.2,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });
      const shieldCurtainMesh = new THREE.Mesh(shieldCurtainGeo, shieldCurtainMat);
      shieldCurtainMesh.position.y = shieldCurtainHeight * 0.5 + 0.03;
      padGroup.add(shieldCurtainMesh);

      const shieldTopRimGeo = new THREE.TorusGeometry(shieldRadius, 0.042, 8, 48);
      shieldTopRimGeo.rotateX(Math.PI / 2);
      const shieldTopRimMat = new THREE.MeshBasicMaterial({
        color: shieldColorHex,
        transparent: true,
        opacity: 0.62,
        depthWrite: false,
      });
      const shieldTopRimMesh = new THREE.Mesh(shieldTopRimGeo, shieldTopRimMat);
      shieldTopRimMesh.position.y = shieldCurtainHeight + 0.03;
      padGroup.add(shieldTopRimMesh);

      const slotMeshes: THREE.Group[] = [];
      const slotGeo = new THREE.BoxGeometry(
        UNIFIED_WORLD_CRATE_SIZE,
        UNIFIED_WORLD_CRATE_SIZE,
        UNIFIED_WORLD_CRATE_SIZE,
      );
      for (let i = 0; i < 8; i++) {
        const layer = i < 4 ? 0 : 1;
        const [tx, tz] = tileOffsets[i % 4];
        const slotY = 0.93 + layer * UNIFIED_WORLD_CRATE_SIZE;
        const slotGrp = new THREE.Group();
        slotGrp.position.set(tx, slotY, tz);
        slotGrp.visible = false;
        addOutlinedPart(slotGrp, slotGeo, matRedCrate, [0, 0, 0], [0, 0, 0], 1.07, true);
        populateRealBlitzCrateBoxFromGlb(
          slotGrp,
          'red',
          loadedBlitzAssets,
          windUniforms,
          isSoftwareGl,
          UNIFIED_WORLD_CRATE_SIZE,
        );
        padGroup.add(slotGrp);
        slotMeshes.push(slotGrp);
      }

      const padSign = createBillboardSign(4.8, 1.15);
      padSign.sprite.position.set(0, 3.85, 0);
      padSign.sprite.visible = false;

      return {
        spec,
        padGroup,
        shieldCurtainMat,
        shieldFloorRingMat,
        worldX: spec.x,
        worldZ: spec.z,
        slotMeshes,
        padSign,
      };
    };
    const publicWarzonePads = PUBLIC_WARZONE_CRATE_PADS.map((spec) =>
      buildPublicWarzoneCratePadMesh(spec),
    );
    const horizonBackdrop = buildHorizonCliffBackdrop3D(scene, {
      isSoftwareGl,
      leafMaskTexture: loadedBlitzAssets?.treeFoliageTex ?? getSharedFallbackFoliageMaskTexture(),
      windUniforms,
    });
    enableSceneLinearFog(scene);

    const INTERACT_ENTER_RADIUS = 2.6;
    const INTERACT_EXIT_RADIUS = 2.9;
    const scratchKioskWorldPos = new THREE.Vector3();
    const getKioskWorldCenterForPlot = (team: 'blue' | 'red', padIdx = 0): THREE.Vector3 => {
      const baseObj = team === 'blue' ? blueBase : redBase;
      const pad = baseObj.commanderPads[padIdx] ?? baseObj.commanderPads[0];
      pad.kioskMesh.updateWorldMatrix(true, false);
      return pad.kioskMesh.getWorldPosition(scratchKioskWorldPos);
    };
    const getBlueKioskWorldCenter = (padIdx = 0): THREE.Vector3 =>
      getKioskWorldCenterForPlot('blue', padIdx);

    // =========================================================================
    // 6. MAP LAYOUT STATE & REAL .GLB PROP / TREE BUILDER (8-10 UNIT TALL TREES!)
    // =========================================================================
    const loadSavedLayout = (): ArenaMapLayout => loadSavedArenaLayout();

    let currentMapLayout: ArenaMapLayout = loadSavedLayout();
    const trees: DestructibleTree[] = [];
    const activeMapProps: ActiveMapPropPhysics[] = [];
    const worldPropBatchManager = new InstancedWorldPropBatchManager('WorldMapInstancedProps');
    scene.add(worldPropBatchManager.batchRootGroup);

    type SharedPropTemplatePart = {
      geometry: THREE.BufferGeometry;
      material: THREE.Material;
      castShadow: boolean;
      receiveShadow: boolean;
      isModelStroke: boolean;
    };
    let cachedRiverRockTemplateParts: SharedPropTemplatePart[] | null = null;
    const getSharedRiverRockTemplateParts = (): SharedPropTemplatePart[] => {
      if (cachedRiverRockTemplateParts) return cachedRiverRockTemplateParts;
      const tmp = new THREE.Group();
      const stoneGeo = new THREE.SphereGeometry(0.68, 9, 7);
      const addStoneLobe = (
        colorHex: string,
        sx: number,
        sy: number,
        sz: number,
        px: number,
        py: number,
        pz: number,
        strokeW: number,
      ) => {
        const m = new THREE.Mesh(stoneGeo, new THREE.MeshToonMaterial({ color: colorHex }));
        m.scale.set(sx, sy, sz);
        m.position.set(px, py, pz);
        upgradeMeshToBlitzWorldMaterial(m, windUniforms, colorHex, 0.22);
        const st = createBlitzStrokeMesh(stoneGeo, strokeW);
        if (st) m.add(st);
        tmp.add(m);
      };
      addStoneLobe('#7b8d7e', 1.28, 0.74, 1.08, 0, 0.24, 0, 0.02);
      addStoneLobe('#82cc59', 0.96, 0.4, 0.84, 0, 0.5, 0, 0.018);
      addStoneLobe('#5f7063', 0.62, 0.46, 0.58, 0.65, 0.14, 0.32, 0.018);
      bakeStaticGroupMeshes(tmp, { minShadowCasterSpan: 0.45 });
      cachedRiverRockTemplateParts = [];
      tmp.traverse((node) => {
        const m = node as THREE.Mesh;
        if (m.isMesh && !Array.isArray(m.material)) {
          if (!m.geometry.boundingSphere) m.geometry.computeBoundingSphere();
          cachedRiverRockTemplateParts!.push({
            geometry: m.geometry,
            material: m.material,
            castShadow: m.castShadow,
            receiveShadow: m.receiveShadow,
            isModelStroke: Boolean(m.userData?.isModelStroke),
          });
        }
      });
      stoneGeo.dispose();
      return cachedRiverRockTemplateParts;
    };

    interface ParkFlowerSpotSpec {
      x: number;
      y: number;
      z: number;
      rotY: number;
      scale: number;
      seed: number;
    }
    const pendingParkFlowerSpots: ParkFlowerSpotSpec[] = [];
    let disposeActiveParkFlowerBatch: (() => void) | null = null;

    const clonePropGroupFromTemplate = (parts: readonly SharedPropTemplatePart[]): THREE.Group => {
      const grp = new THREE.Group();
      for (let i = 0; i < parts.length; i++) {
        const p = parts[i];
        const m = new THREE.Mesh(p.geometry, p.material);
        m.castShadow = p.castShadow;
        m.receiveShadow = p.receiveShadow;
        m.frustumCulled = true;
        if (p.isModelStroke) m.userData.isModelStroke = true;
        grp.add(m);
      }
      return grp;
    };
    let navGridDirty = true;
    let cachedFootNavGrid: AStarNavGrid | null = null;
    let cachedVehicleNavGrid: AStarNavGrid | null = null;
    let cachedPedestrianNavGrid: AStarNavGrid | null = null;
    const collisionCooldownMap = new Map<string, number>();
    let nextEntityId = 500;
    let editorRotY = 0;
    let editorScale = 1.0;

    const registerMapPropPhysics = (prop: PlacedMapProp, wrapper: THREE.Group) => {
      const spec = getPropCollisionSpec(prop.kind, prop.scale);
      if (spec.category === 'none') return;
      const calibratedHeightY =
        typeof wrapper.userData.calibratedHeightY === 'number'
          ? wrapper.userData.calibratedHeightY
          : getPropBaseHeight(prop.kind) * prop.scale;
      wrapper.userData.baseColliderSpec = {
        radius: spec.radius,
        halfX: spec.halfX,
        halfZ: spec.halfZ,
        heightY: calibratedHeightY,
      };
      activeMapProps.push({
        id: prop.id,
        kind: prop.kind,
        wrapper,
        x: prop.x,
        z: prop.z,
        vx: 0,
        vz: 0,
        rotY: prop.rotY,
        rotVelY: 0,
        scale: prop.scale,
        category: spec.category,
        materialTag: spec.materialTag,
        radius: spec.radius,
        halfX: spec.halfX,
        halfZ: spec.halfZ,
        heightY: calibratedHeightY,
        mass: spec.mass,
        restitution: spec.restitution,
        destructible: spec.destructible,
        hp: spec.maxHp,
        maxHp: spec.maxHp,
        shootImpulse: spec.shootImpulse,
        canJiggleOnHit: spec.canJiggleOnHit,
        alive: true,
        jiggleTimer: 0,
        jiggleDirX: 0,
        jiggleDirZ: 1,
      });
    };

    const spawnSingleMapProp = (prop: PlacedMapProp) => {
      if (playModeRef.current !== 'editor') {
        const overlapsPublicShieldPad = PUBLIC_WARZONE_CRATE_PADS.some(
          (pad) =>
            Math.hypot(prop.x - pad.x, prop.z - pad.z) <
            (pad.shieldRadius ?? PUBLIC_PAD_SHIELD_RADIUS) + 1.1,
        );
        // Prevent any default tree/prop from spawning inside the Central Plaza Halte platform deck or inside the South Plaza L-Shaped Glasshouse Cafe
        const overlapsHaltePlatform =
          prop.x >= -62.5 && prop.x <= -55.3 && Math.abs(prop.z) <= 9.6;
        const overlapsGlasshouseCafe =
          prop.id === 491 || isInsideSouthPlazaGlasshouseFootprint(prop.x, prop.z);
        if (overlapsPublicShieldPad || overlapsHaltePlatform || overlapsGlasshouseCafe) {
          return;
        }
      }
      if (prop.kind === 'tree_purple' || prop.kind === 'tree_gold') {
        const isPurple = prop.kind === 'tree_purple';
        const sidewalkLiftY =
          isPointOnOuterTramSidewalk(prop.x, prop.z) || isPointOnInnerTramSidewalk(prop.x, prop.z)
            ? 0.09
            : 0;
        const grp = new THREE.Group();
        grp.position.set(prop.x, sidewalkLiftY, prop.z);
        grp.rotation.y = prop.rotY;
        grp.userData.baseRotY = prop.rotY;
        grp.userData.extraLiftY = sidewalkLiftY;
        const shadow = new THREE.Mesh(shadowDiscGeo, shadowDiscMat);
        shadow.name = 'ContactShadowDisc';
        shadow.position.y = 0.02;
        shadow.scale.setScalar(2.35 * prop.scale);
        grp.add(shadow);
        scene.add(grp);

        populateRealBlitzTreeFromGlb(
          grp,
          loadedBlitzAssets
            ? isPurple
              ? loadedBlitzAssets.tree1bGltf?.scene ?? null
              : loadedBlitzAssets.tree1aGltf?.scene ?? null
            : null,
          isPurple,
          loadedBlitzAssets ? loadedBlitzAssets.treeFoliageTex : getSharedFallbackFoliageMaskTexture(),
          windUniforms,
          isSoftwareGl,
          prop.scale,
        );

        trees.push({
          id: nextEntityId++,
          propId: prop.id,
          isPurple,
          scale: prop.scale,
          mesh: grp,
          x: prop.x,
          z: prop.z,
          hp: 45,
          maxHp: 45,
          alive: true,
          hitFlashTimer: 0,
          jiggleTimer: 0,
          jiggleIntensity: 0,
          jiggleDirX: 0,
          jiggleDirZ: 1,
        });
        return;
      }

      if (prop.kind === 'river_rock') {
        const rockGrp = clonePropGroupFromTemplate(getSharedRiverRockTemplateParts());
        const sc = prop.scale;
        rockGrp.scale.setScalar(sc);
        rockGrp.position.set(prop.x, getTerrainElevation(prop.x, prop.z), prop.z);
        rockGrp.rotation.y = prop.rotY;
        rockGrp.userData.propId = prop.id;
        rockGrp.userData.worldX = prop.x;
        rockGrp.userData.worldZ = prop.z;
        rockGrp.userData.baseRotY = prop.rotY;
        realPropsGroup.add(rockGrp);
        registerMapPropPhysics(prop, rockGrp);
        return;
      }

      if (prop.kind === 'flower_cluster') {
        pendingParkFlowerSpots.push({
          x: prop.x,
          y: getTerrainElevation(prop.x, prop.z),
          z: prop.z,
          rotY: prop.rotY,
          scale: prop.scale,
          seed: prop.id,
        });
        return;
      }

      // In Sandbox / Match mode, any 'dump_truck' placed on the map becomes a real drivable Dump Truck vehicle!
      if (prop.kind === 'dump_truck' && playModeRef.current !== 'editor') {
        const existingTruck = tanks.find(
          (v) => v.vehicleKind === 'truck' && (v.mapPropId === prop.id || Math.hypot(v.x - prop.x, v.z - prop.z) < 2.2),
        );
        if (!existingTruck) {
          const truckTeam = prop.x <= 0 ? 'blue' : 'red';
          const mapTruck = createBlitzDumpTruckVehicle(prop.x, prop.z, truckTeam, prop.rotY);
          mapTruck.mapPropId = prop.id;
          tanks.push(mapTruck);
        }
        return;
      }

      if (!loadedBlitzAssets) {
        const placeholderWrapper = new THREE.Group();
        placeholderWrapper.position.set(prop.x, 0, prop.z);
        placeholderWrapper.rotation.y = prop.rotY;
        placeholderWrapper.userData.propId = prop.id;
        placeholderWrapper.userData.worldX = prop.x;
        placeholderWrapper.userData.worldZ = prop.z;
        placeholderWrapper.userData.baseRotY = prop.rotY;
        realPropsGroup.add(placeholderWrapper);
        registerMapPropPhysics(prop, placeholderWrapper);
        return;
      }
      const gltfMap: Record<
        Exclude<PlacedMapProp['kind'], 'tree_purple' | 'tree_gold' | 'river_rock' | 'flower_cluster'>,
        typeof loadedBlitzAssets.turbineGltf
      > = {
        turbine: loadedBlitzAssets.turbineGltf,
        power_core: loadedBlitzAssets.powerCoreGltf,
        concrete_fence: loadedBlitzAssets.concreteFenceGltf,
        barricade: loadedBlitzAssets.barricadeGltf,
        explosive_barrel: loadedBlitzAssets.explosiveBarrelGltf,
        hydrant: loadedBlitzAssets.hydrantGltf,
        lamppost_1a: loadedBlitzAssets.lamppost1aGltf,
        lamppost_1b: loadedBlitzAssets.lamppost1bGltf,
        bench: loadedBlitzAssets.benchGltf,
        chimney: loadedBlitzAssets.chimneyGltf,
        giant_tank: loadedBlitzAssets.giantTankGltf,
        dump_truck: loadedBlitzAssets.dumpTruckGltf,
        crane: loadedBlitzAssets.craneGltf,
        recycle_bin: loadedBlitzAssets.recycleBinGltf,
        traffic_cone: loadedBlitzAssets.trafficConeGltf,
        wheelbarrow: loadedBlitzAssets.wheelbarrowGltf,
        tank_1a: loadedBlitzAssets.tank1aGltf,
        tank_1b: loadedBlitzAssets.tank1bGltf,
        pipe_cluster: loadedBlitzAssets.pipeCluster1aGltf,
        pipe_cluster_1b: loadedBlitzAssets.pipeCluster1bGltf,
        giant_pipe: loadedBlitzAssets.giantPipe1aGltf,
        giant_pipe_1b: loadedBlitzAssets.giantPipe1bGltf,
        concrete_fence_1b: loadedBlitzAssets.concreteFence1bGltf,
        concrete_pipe: loadedBlitzAssets.concretePipeGltf,
        barrel_1c: loadedBlitzAssets.barrel1cGltf,
        pallet_1a: loadedBlitzAssets.pallet1aGltf,
        h_beam: loadedBlitzAssets.hBeamGltf,
        forklift: loadedBlitzAssets.forkliftGltf,
        fuel_cell: loadedBlitzAssets.fuelGltf,
        circuit_module: loadedBlitzAssets.circuitGltf,
      };
      const targetGltf = gltfMap[prop.kind];
      const baseH = getPropBaseHeight(prop.kind) * prop.scale;
      const wrapper = spawnRealBlitzPropFromGlb(
        realPropsGroup,
        targetGltf,
        prop.x,
        prop.z,
        prop.rotY,
        baseH,
        windUniforms,
        isSoftwareGl,
      );
      if (wrapper) {
        const sidewalkLiftY =
          isPointOnOuterTramSidewalk(prop.x, prop.z) || isPointOnInnerTramSidewalk(prop.x, prop.z)
            ? 0.09
            : 0;
        wrapper.position.y = sidewalkLiftY;
        wrapper.userData.propId = prop.id;
        wrapper.userData.worldX = prop.x;
        wrapper.userData.worldZ = prop.z;
        wrapper.userData.baseRotY = prop.rotY;
        wrapper.userData.extraLiftY = sidewalkLiftY;
        const propColSpec = getPropCollisionSpec(prop.kind, prop.scale);
        if (propColSpec.category === 'pushable' || prop.kind === 'explosive_barrel') {
          wrapper.userData.skipStaticInstancing = true;
        }
        registerMapPropPhysics(prop, wrapper);
      }
    };

    const rebuildMapFromLayout = (layout: ArenaMapLayout) => {
      // 1. Reposition Blue HQ, 4 Blue Stacking Pads, Red HQ, 4 Red Stacking Pads, and Central Drop Zone
      blueBase.hqX = layout.blueHq.x;
      blueBase.hqZ = layout.blueHq.z;
      blueBase.baseGroup.position.set(layout.blueHq.x, 0, layout.blueHq.z);
      blueBase.baseGroup.rotation.y = Math.PI / 2;

      const padOffsetsX = [-37.7, -7.7, 22.3, 52.3];
      blueBase.commanderPads.forEach((cp, idx) => {
        cp.padX = layout.blueHq.x + padOffsetsX[idx];
        cp.padZ = layout.blueHq.z - 8.2;
        cp.worldX = cp.padX;
        cp.worldZ = cp.padZ;
        cp.padGroup.position.set(cp.padX, 0.04, cp.padZ);
        cp.padGroup.rotation.y = 0;
      });
      blueBase.padX = blueBase.commanderPads[0].padX;
      blueBase.padZ = blueBase.commanderPads[0].padZ;

      redBase.hqX = layout.redHq.x;
      redBase.hqZ = layout.redHq.z;
      redBase.baseGroup.position.set(layout.redHq.x, 0, layout.redHq.z);
      redBase.baseGroup.rotation.y = -Math.PI / 2;

      redBase.commanderPads.forEach((cp, idx) => {
        cp.padX = layout.redHq.x - padOffsetsX[idx];
        cp.padZ = layout.redHq.z + 8.2;
        cp.worldX = cp.padX;
        cp.worldZ = cp.padZ;
        cp.padGroup.position.set(cp.padX, 0.04, cp.padZ);
        cp.padGroup.rotation.y = Math.PI;
      });
      redBase.padX = redBase.commanderPads[0].padX;
      redBase.padZ = redBase.commanderPads[0].padZ;

      centerDropZoneGroup.position.set(layout.centerDropZone.x, 0.06, layout.centerDropZone.z);

      // 2. Clear existing trees & props (and any unmounted map-prop dump trucks if in editor mode)
      trees.forEach((t) => scene.remove(t.mesh));
      trees.length = 0;
      activeMapProps.length = 0;
      for (let i = realPropsGroup.children.length - 1; i >= 0; i--) {
        realPropsGroup.remove(realPropsGroup.children[i]);
      }
      if (playModeRef.current === 'editor') {
        for (let i = tanks.length - 1; i >= 0; i--) {
          if (tanks[i].mapPropId !== undefined && tanks[i] !== mountedTank) {
            scene.remove(tanks[i].root);
            tanks.splice(i, 1);
          }
        }
      }

      // 3. Spawn all trees & props from layout, then promote repetitive props & trees into GPU-instanced batches
      worldPropBatchManager.clear();
      pendingParkFlowerSpots.length = 0;
      disposeActiveParkFlowerBatch?.();
      disposeActiveParkFlowerBatch = null;
      layout.props.forEach((p) => spawnSingleMapProp(p));
      if (pendingParkFlowerSpots.length > 0) {
        const parkFlowerBatch = curvedPlanetEnv.buildCentralPlazaParkFlowerBatch(
          pendingParkFlowerSpots,
          'ParkCentralPlazaFlowers',
        );
        curvedPlanetEnv.natureGroup.add(parkFlowerBatch.group);
        disposeActiveParkFlowerBatch = parkFlowerBatch.dispose;
      }
      worldPropBatchManager.promoteTreesToInstancedBatches(trees);
      worldPropBatchManager.setTreeFoliageShadowsEnabled(activeFoliageShadowsEnabled);
      worldPropBatchManager.promoteStaticPropsToInstancedBatches(realPropsGroup.children, 2);
      scene.userData.__staticWorldAligned = false;
      navGridDirty = true;
    };

    type UnitFootRingVariant = 'blue' | 'red' | 'neutral' | 'selected';
    const sharedUnitFootRingGeo = new THREE.RingGeometry(0.76, 0.86, 48);
    const sharedUnitFootDiscGeo = new THREE.CircleGeometry(0.76, 48);
    const sharedUnitFootRingMats: Record<UnitFootRingVariant, THREE.MeshBasicMaterial> = {
      blue: new THREE.MeshBasicMaterial({
        color: getUnitFootRingTeamColor('blue').hexInt,
        transparent: true,
        opacity: 0.9,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
      red: new THREE.MeshBasicMaterial({
        color: getUnitFootRingTeamColor('red').hexInt,
        transparent: true,
        opacity: 0.9,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
      neutral: new THREE.MeshBasicMaterial({
        color: 0xe2e8f0,
        transparent: true,
        opacity: 0.55,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
      selected: new THREE.MeshBasicMaterial({
        color: 0x22c55e,
        transparent: true,
        opacity: 0.95,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
    };
    const sharedUnitFootDiscMats: Record<UnitFootRingVariant, THREE.MeshBasicMaterial> = {
      blue: new THREE.MeshBasicMaterial({
        color: getUnitFootRingTeamColor('blue').hexInt,
        transparent: true,
        opacity: 0.14,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
      red: new THREE.MeshBasicMaterial({
        color: getUnitFootRingTeamColor('red').hexInt,
        transparent: true,
        opacity: 0.14,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
      neutral: new THREE.MeshBasicMaterial({
        color: 0xe2e8f0,
        transparent: true,
        opacity: 0.12,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
      selected: new THREE.MeshBasicMaterial({
        color: 0x22c55e,
        transparent: true,
        opacity: 0.2,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
    };

    // =========================================================================
    // 7. BUILDER FOR CHIBI/BLOCKY BUDDIES BLITZ CHARACTERS & REAL .GLB BLITZ TANKS
    // =========================================================================
    const createBuddyCharacterUnit = (
      team: 'blue' | 'red',
      isPlayer: boolean,
      classId: BuddyClassId,
      spawnX: number,
      spawnZ: number,
      ownerCommanderId = 0,
      startUnarmed = true,
      isStarterCommanderUnit = true,
      preferredGender?: CharacterGender,
      customDisplayName?: string,
    ): BuddyUnit => {
      const root = new THREE.Group();
      root.rotation.order = 'YXZ';
      root.position.set(spawnX, 0, spawnZ);
      scene.add(root);

      const shadow = new THREE.Mesh(shadowDiscGeo, avatarContactShadowMat);
      shadow.position.y = 0.032;
      shadow.scale.setScalar(0.68);
      shadow.renderOrder = 1;
      root.add(shadow);

      const teamRing = new THREE.Mesh(sharedUnitFootRingGeo, sharedUnitFootRingMats[team]);
      teamRing.name = 'unitFootTeamRing';
      teamRing.rotation.x = -Math.PI / 2;
      teamRing.position.y = 0.04;
      const innerFootDisc = new THREE.Mesh(sharedUnitFootDiscGeo, sharedUnitFootDiscMats[team]);
      innerFootDisc.name = 'unitFootInnerGlowDisc';
      innerFootDisc.position.z = -0.005;
      teamRing.add(innerFootDisc);
      teamRing.scale.setScalar(0.845);
      root.add(teamRing);

      const bodyGroup = new THREE.Group();
      bodyGroup.rotation.order = 'YXZ';
      // Cara 1 Lock-Step World Scaling: 0.98 (0.845x of 1.16) makes the entire World +18.4% larger relative to the avatar
      bodyGroup.scale.setScalar(0.98);
      if (isPlayer) {
        bodyGroup.userData.enableAvatarCastShadow = false;
      }
      bodyGroup.userData.disableNpcOutline = true;
      root.add(bodyGroup);

      const rig = buildProceduralBuddyAvatar(
        bodyGroup,
        team,
        windUniforms,
        isSoftwareGl,
        false,
        preferredGender,
        isPlayer,
      );
      const {
        headMesh,
        leftArmPivot,
        rightArmPivot,
        leftLegPivot,
        rightLegPivot,
        weaponMesh,
      } = rig;
      headMesh.userData.defaultMat = headMesh.material;

      // Overhead Carried 3D Crate (visible when carrying a crate in front of chest between both hands; inverse-scaled by 1/0.98 so world size is 1:1 UNIFIED_WORLD_CRATE_SIZE!)
      const overheadCrateGroup = new THREE.Group();
      overheadCrateGroup.name = 'BuddyOverheadCrateGroup';
      overheadCrateGroup.position.set(0, 1.96, 0.72);
      overheadCrateGroup.scale.setScalar(1 / 0.98);
      overheadCrateGroup.visible = false;
      bodyGroup.add(overheadCrateGroup);
      const overheadCrateBox = addOutlinedPart(
        overheadCrateGroup,
        new THREE.BoxGeometry(
          UNIFIED_WORLD_CRATE_SIZE,
          UNIFIED_WORLD_CRATE_SIZE,
          UNIFIED_WORLD_CRATE_SIZE,
        ),
        matRedCrate,
        [0, 0, 0],
      );
      populateRealBlitzCrateBoxFromGlb(
        overheadCrateGroup,
        'red',
        loadedBlitzAssets,
        windUniforms,
        isSoftwareGl,
        UNIFIED_WORLD_CRATE_SIZE,
      );

      // Overhead AI Salute Sign (pops up above AI Buddy head when [V] command is issued!)
      const saluteSign = createBillboardSign(3.4, 0.92);
      saluteSign.sprite.position.set(0, 4.15, 0);
      saluteSign.sprite.visible = false;

      // MMORPG Glassmorphic Nameplate with Default Rookie Emblem (Single-Line Above Head)
      const nameplate = createGlassmorphicNameplate(
        2.8,
        0.72,
        isPlayer ? playerCustomDisplayName : (customDisplayName ?? `BUDDY #${nextEntityId}`),
        '',
        false,
        isPlayer ? playerRoleBadge : undefined,
      );
      nameplate.sprite.position.set(0, NAMEPLATE_SCREEN_SPEC.standingHeadAnchorLocalY, 0);
      nameplate.sprite.visible = false;
      root.add(nameplate.sprite);

      const stunMesh = createBlitzStunEffectMesh();
      stunMesh.name = 'BuddyStunEffect';
      stunMesh.position.set(0, 3.6, 0);
      bodyGroup.add(stunMesh);

      const initialWeaponId: BlitzWeaponId = startUnarmed
        ? 'unarmed'
        : classId === 'Commando' || classId === 'Cyborg' || classId === 'SuperBuddie'
        ? 'bazooka'
        : classId === 'Infuntry' || classId === 'Stealthy'
        ? 'rifle'
        : 'pistol';
      const initialWeaponName =
        initialWeaponId === 'unarmed'
          ? 'Unarmed (Fists)'
          : initialWeaponId === 'bazooka'
          ? 'BlitzRocketLauncher'
          : initialWeaponId === 'rifle'
          ? 'BlitzAssaultRifle'
          : 'BlitzPistol';
      const initialSecondaryItem: BuddySecondaryItemId = startUnarmed
        ? 'none'
        : classId === 'Stealthy' || classId === 'Ninja'
          ? 'land_mine'
          : 'hand_grenade';
      const initialSecondaryCount = initialSecondaryItem === 'none' ? 0 : 2;
      const initialAmmo = initialWeaponId === 'unarmed' ? 0 : initialWeaponId === 'bazooka' ? 18 : 120;
      const tacticalLoadout = createInitialBuddyTacticalLoadout(
        initialWeaponId,
        initialAmmo,
        initialSecondaryItem,
        initialSecondaryCount,
      );
      updateCharacterWeaponStance(rig, initialWeaponId, 0, false, false, 0, 0);

      return {
        id: nextEntityId++,
        team,
        ownerCommanderId,
        isStarterCommanderUnit,
        isPlayer,
        classId,
        root,
        bodyGroup,
        rig,
        headMesh,
        leftArmPivot,
        rightArmPivot,
        leftLegPivot,
        rightLegPivot,
        weaponMesh,
        overheadCrateGroup,
        overheadCrateBox,
        saluteSign,
        nameplate,
        teamRing,
        x: spawnX,
        y: 0,
        z: spawnZ,
        vx: 0,
        vy: 0,
        vz: 0,
        jumpOffset: 0,
        isGrounded: true,
        jumpBufferTimer: 0,
        invincibilityTimer: 0,
        yaw: team === 'blue' ? Math.PI / 2 : -Math.PI / 2,
        hp: isPlayer ? PLAYER_WARZONE_MAX_HP : 100,
        maxHp: isPlayer ? PLAYER_WARZONE_MAX_HP : 100,
        weaponId: initialWeaponId,
        weaponName: initialWeaponName,
        weaponRecoil: 0,
        punchTimer: 0,
        punchHand: 'right',
        kickTimer: 0,
        ammo: initialAmmo,
        carryingCrate: 'none',
        secondaryItem: initialSecondaryItem,
        secondaryCount: initialSecondaryCount,
        tacticalLoadout,
        missionItem: 'none',
        walkCycle: 0,
        shootCooldown: 0,
        hitFlashTimer: 0,
        hitReactionTimer: 0,
        hitReactionDirX: 0,
        hitReactionDirZ: 1,
        stunTimer: 0,
        stunMesh,
        isFrozen: false,
        frozenTimer: 0,
        saluteTimer: 0,
        aiTargetCrateId: null,
        assignedRole: team === 'blue' && ownerCommanderId === 0 ? teamCommand : 'HARVEST',
        followerReactionTimer: 0,
        followerIdleLookTimer: 1.5,
        followerIdleLookYaw: team === 'blue' ? Math.PI / 2 : -Math.PI / 2,
        followerStrafeTimer: 0.8,
        followerStrafeSign: 1,
        alive: true,
        respawnTimer: 0,
      };
    };

    // =========================================================================
    // 1B. STANDING 3D NPC MERCHANTS (LOBBY MINI CAFÉ & EAST BEACH HOUSE)
    //     + 3D PRIVATE HOUSE INTERIOR ROOM (WITH DYNAMIC FURNITURE SLOTS)
    // =========================================================================
    const buildStandingNpcMerchant3D = (
      wx: number,
      _wy: number,
      wz: number,
      rotY: number,
      teamStyle: 'blue' | 'red',
      titleText: string,
      _subText: string,
      preferredGender: CharacterGender = 'female',
    ) => {
      const npcGrp = new THREE.Group();
      npcGrp.rotation.order = 'YXZ';
      const actualGroundY = getTerrainElevation(wx, wz);
      npcGrp.position.set(wx, actualGroundY, wz);
      npcGrp.rotation.y = rotY;
      scene.add(npcGrp);

      const npcShadow = new THREE.Mesh(shadowDiscGeo, avatarContactShadowMat);
      npcShadow.position.y = 0.032;
      npcShadow.scale.setScalar(0.68);
      npcShadow.renderOrder = 1;
      npcGrp.add(npcShadow);

      const npcRing = new THREE.Mesh(
        new THREE.RingGeometry(0.82, 0.96, 48),
        new THREE.MeshBasicMaterial({
          color: 0x22c55e,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.92,
        }),
      );
      npcRing.rotation.x = -Math.PI / 2;
      npcRing.position.y = 0.04;
      npcRing.scale.setScalar(0.845);
      npcGrp.add(npcRing);

      const bodyGrp = new THREE.Group();
      bodyGrp.rotation.order = 'YXZ';
      // 1:1 identical scale (0.98) with playerUnit.bodyGroup so Hana & Kai stand at the exact same height as the player character
      bodyGrp.scale.setScalar(0.98);
      bodyGrp.userData.disableNpcOutline = true;
      npcGrp.add(bodyGrp);

      const npcRig = buildProceduralBuddyAvatar(
        bodyGrp,
        teamStyle,
        windUniforms,
        isSoftwareGl,
        false,
        preferredGender,
      );
      npcRig.weaponRigGroup.visible = false;
      npcRig.pistolGroup.visible = false;

      // MMORPG Crystal-Clear Glassmorphism Nameplate with Special Golden NPC Crown Crest Emblem (Single-Line Above Head)
      const npcNameplate = createGlassmorphicNameplate(
        2.9,
        0.74,
        titleText.split('//')[0].trim(),
        '',
        true,
      );
      npcNameplate.sprite.position.set(0, NAMEPLATE_SCREEN_SPEC.npcHeadAnchorLocalY, 0);
      npcNameplate.sprite.visible = false;
      npcGrp.add(npcNameplate.sprite);

      // Stylized 3D Anime MMORPG Floating Exclamation Mark Indicator ('!')
      const exclamationGroup = new THREE.Group();
      exclamationGroup.name = 'NpcExclamationMark';
      exclamationGroup.position.set(0, 3.25, 0);

      // Glow backing disc / halo ring
      const haloDisc = new THREE.Mesh(
        new THREE.RingGeometry(0.18, 0.58, 24),
        new THREE.MeshBasicMaterial({
          color: 0x38bdf8,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.38,
          depthWrite: false,
        }),
      );
      haloDisc.name = 'HaloDisc';
      exclamationGroup.add(haloDisc);

      // Diamond / Diamond-rhombus background badge
      const badgeGeo = new THREE.CylinderGeometry(0.55, 0.55, 0.08, 4);
      badgeGeo.rotateX(Math.PI / 2);
      badgeGeo.rotateZ(Math.PI / 4);
      const badgeMesh = new THREE.Mesh(
        badgeGeo,
        new THREE.MeshStandardMaterial({
          color: 0x0284c7,
          roughness: 0.25,
          metalness: 0.1,
          emissive: 0x0369a1,
          emissiveIntensity: 0.35,
        }),
      );
      badgeMesh.scale.set(0.85, 1.25, 1.0);
      exclamationGroup.add(badgeMesh);

      // Upper pillar bar of '!'
      const barGeo = new THREE.CylinderGeometry(0.085, 0.055, 0.52, 12);
      const markMat = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        roughness: 0.2,
        metalness: 0.05,
        emissive: 0xe0f2fe,
        emissiveIntensity: 0.5,
      });
      const barMesh = new THREE.Mesh(barGeo, markMat);
      barMesh.position.set(0, 0.11, 0.06);
      exclamationGroup.add(barMesh);

      // Lower dot of '!'
      const dotGeo = new THREE.SphereGeometry(0.065, 12, 12);
      const dotMesh = new THREE.Mesh(dotGeo, markMat);
      dotMesh.position.set(0, -0.25, 0.06);
      exclamationGroup.add(dotMesh);
      exclamationGroup.visible = false;

      npcGrp.add(exclamationGroup);

      // Compact Ring-less 3D Blue->Green Interaction Triangle above Merchant's Head
      const merchantChevron = buildCompactInteractiveChevronMarker(0.15, 0.28, '#38bdf8');
      merchantChevron.group.position.set(0, 3.68, 0);
      npcGrp.add(merchantChevron.group);

      return { npcGrp, bodyGrp, npcRig, npcNameplate, exclamationGroup, merchantChevron };
    };

    const lobbyCafeNpc = buildStandingNpcMerchant3D(
      REAL_ESTATE_FURNITURE_KIOSK_LAYOUT.hanaMerchantWorld.x,
      getTerrainElevation(
        REAL_ESTATE_FURNITURE_KIOSK_LAYOUT.hanaMerchantWorld.x,
        REAL_ESTATE_FURNITURE_KIOSK_LAYOUT.hanaMerchantWorld.z,
      ),
      REAL_ESTATE_FURNITURE_KIOSK_LAYOUT.hanaMerchantWorld.z,
      REAL_ESTATE_FURNITURE_KIOSK_LAYOUT.hanaMerchantWorld.rotY,
      'blue',
      'HANA',
      'PROPERTY AGENT & CITY GUIDE',
      'female',
    );
    lobbyCafeNpc.npcRig.idleClipOverrideName = 'hana_idle.001';
    const beachHouseNpc = buildStandingNpcMerchant3D(
      85.8,
      getTerrainElevation(85.8, 60.0),
      60.0,
      Math.PI / 2,
      'red',
      'KAI',
      'FISHERMAN & BEACH KEEPER',
      'male',
    );
    beachHouseNpc.npcRig.idleClipOverrideName = 'kai_idle.001';

    // =========================================================================
    // LIVING CITY AMBIENT CITIZEN NPCS (Shared Humanoid GLB Avatars + Activities)
    // Stagger-upgraded 1 GLB clone per frame, distance-culled, hidden in interiors/Warzone.
    // =========================================================================
    interface CityAmbientNpcController {
      preset: CityAmbientNpcPreset;
      root: THREE.Group;
      bodyGroup: THREE.Group;
      shadowMesh: THREE.Mesh;
      rig: ReturnType<typeof buildProceduralBuddyAvatar>;
      nameplate: ReturnType<typeof createGlassmorphicNameplate>;
      x: number;
      z: number;
      yaw: number;
      waypointIdx: number;
      pauseTimer: number;
      walkCycle: number;
      speedMps: number;
      isMoving: boolean;
      isSitting: boolean;
      activeActivity: CityAmbientNpcActivity;
      activeStatusLabel: string;
      activeSeatLiftY: number;
      activeHoldingCafeItemId: CafeMenuItemId | null;
      navPath: Array<{ x: number; z: number }>;
      navWaypointIndex: number;
      navPathGoalKey: string;
      stuckTimer: number;
      lastProgressX: number;
      lastProgressZ: number;
      avoidSide: number;
      avoidTimer: number;
      seatOverride: NpcSeatOverrideState | null;
      seedPhase: number;
      nextFishCastSec: number;
      glbUpgraded: boolean;
      rodUpgraded: boolean;
    }

    const applyAmbientNpcClipOverrides = (
      rig: ReturnType<typeof buildProceduralBuddyAvatar>,
      preset: CityAmbientNpcPreset | null | undefined,
      fallbackIdleClipName?: string,
    ): void => {
      const nextIdle = preset?.idleOverrideClip ?? fallbackIdleClipName;
      if (rig.idleClipOverrideName !== nextIdle) rig.idleClipOverrideName = nextIdle;
      if (rig.walkClipOverrideName !== preset?.walkOverrideClip) {
        rig.walkClipOverrideName = preset?.walkOverrideClip;
      }
      if (rig.runClipOverrideName !== preset?.runOverrideClip) {
        rig.runClipOverrideName = preset?.runOverrideClip;
      }
      if (rig.sitClipOverrideName !== preset?.sitOverrideClip) {
        rig.sitClipOverrideName = preset?.sitOverrideClip;
      }
    };

    const resolveAmbientSeatBackShift = (x: number, z: number): number => {
      if (
        Math.hypot(x - 2.0, z - -34.5) < 1.5 ||
        Math.hypot(x - 2.0, z - -29.5) < 1.5 ||
        Math.hypot(x - -1.0, z - 29.8) < 1.5 ||
        Math.hypot(x - -1.0, z - 34.2) < 1.5 ||
        Math.hypot(x - -47.5, z - -10.2) < 1.5 ||
        Math.hypot(x - -47.5, z - 10.2) < 1.5 ||
        Math.hypot(x - -44.2, z - -2.0) < 1.5 ||
        Math.hypot(x - -44.2, z - 2.0) < 1.5 ||
        Math.hypot(x - -9.5, z - -44.6) < 1.5 ||
        Math.hypot(x - -9.5, z - 44.6) < 1.5
      ) {
        return 0.12;
      }
      if (
        Math.hypot(x - 96.2, z - 81.8) < 1.5 ||
        Math.hypot(x - 96.2, z - 85.0) < 1.5 ||
        Math.hypot(x - 96.2, z - 88.2) < 1.5 ||
        Math.hypot(x - 97.5, z - 49.5) < 1.5
      ) {
        return 0.05;
      }
      return 0;
    };

    const resolveCitizenRenderAnchor = (
      npc: CityAmbientNpcController,
      posX: number = npc.x,
      posZ: number = npc.z,
      fallbackYaw: number = npc.yaw,
    ) => {
      const prevIdx =
        (npc.waypointIdx - 1 + npc.preset.waypoints.length) % npc.preset.waypoints.length;
      const arrivedStop =
        npc.seatOverride && npc.seatOverride.wpIdx === prevIdx
          ? npc.seatOverride
          : npc.preset.waypoints[prevIdx];
      const seatFacingYaw = arrivedStop?.yaw ?? fallbackYaw;
      const seatShift = npc.isSitting ? resolveAmbientSeatBackShift(posX, posZ) : 0;
      const renderX = seatShift > 0 ? posX - Math.cos(seatFacingYaw) * seatShift : posX;
      const renderZ = seatShift > 0 ? posZ + Math.sin(seatFacingYaw) * seatShift : posZ;
      const groundY = getTerrainElevation(renderX, renderZ);
      return { seatFacingYaw, renderX, groundY, renderZ };
    };

    // WS10: Per-client post-interaction linger state (25s after dialogue closes, 15m early-end)
    const npcLingerStates = new Map<string, NpcPostInteractionLingerState>();
    const npcWasTalkingMap = new Map<string, boolean>();

    const cityAmbientNpcs: CityAmbientNpcController[] = CITY_AMBIENT_NPC_PRESETS.map(
      (preset, idx) => {
        const initPatrolWaypoints = resolveNpcScheduledPatrolWaypoints(preset.id, 12);
        const startStopIdx =
          preset.waypoints.length > 0 ? idx % preset.waypoints.length : 0;
        const wp0 =
          (initPatrolWaypoints && initPatrolWaypoints[0]) ||
          preset.waypoints[startStopIdx] ||
          { x: 0, z: 0, yaw: 0 };
        const initYaw = wp0.yaw ?? 0;
        const initActivity = wp0.activity ?? preset.activity;
        const initSitting = initActivity === 'sit_relax';
        const hasFishingStop =
          preset.activity === 'fishing' ||
          preset.waypoints.some((w) => w.activity === 'fishing');

        const root = new THREE.Group();
        root.name = `CityAmbientNpc_${preset.id}`;
        root.visible = false;
        scene.add(root);

        const shadowMesh = new THREE.Mesh(shadowDiscGeo, avatarContactShadowMat);
        shadowMesh.position.y = 0.03;
        shadowMesh.scale.setScalar(0.92);
        shadowMesh.renderOrder = 1;
        shadowMesh.visible = !initSitting;
        root.add(shadowMesh);

        const bodyGroup = new THREE.Group();
        bodyGroup.rotation.order = 'YXZ';
        bodyGroup.scale.setScalar(0.98);
        bodyGroup.rotation.set(0, initYaw + Math.PI / 2, 0);
        bodyGroup.userData.enableAvatarCastShadow = false;
        bodyGroup.userData.disableNpcOutline = true;
        root.add(bodyGroup);

        const rig = buildProceduralBuddyAvatar(
          bodyGroup,
          preset.teamTint,
          windUniforms,
          isSoftwareGl,
          false,
          preset.gender,
        );
        applyAmbientNpcClipOverrides(rig, preset);
        rig.weaponRigGroup.visible = false;
        rig.pistolGroup.visible = false;

        const nameplate = createGlassmorphicNameplate(
          2.6,
          0.66,
          preset.displayName.toUpperCase(),
          preset.activityLabel,
          false,
        );
        nameplate.sprite.position.set(
          0,
          initSitting
            ? NAMEPLATE_SCREEN_SPEC.sittingHeadAnchorLocalY
            : NAMEPLATE_SCREEN_SPEC.standingHeadAnchorLocalY,
          0,
        );
        nameplate.sprite.visible = false;
        root.add(nameplate.sprite);

        const seedPhase = idx * 1.73;
        const nextIdx =
          preset.waypoints.length > 1
            ? (startStopIdx + 1) % preset.waypoints.length
            : 0;
        return {
          preset,
          root,
          bodyGroup,
          shadowMesh,
          rig,
          nameplate,
          x: wp0.x,
          z: wp0.z,
          yaw: initYaw,
          waypointIdx: nextIdx,
          pauseTimer: 2.0 + (idx % 4) * 1.2,
          walkCycle: seedPhase,
          speedMps: 0,
          isMoving: false,
          isSitting: initSitting,
          activeActivity: initActivity,
          activeStatusLabel: wp0.label ?? preset.activityLabel,
          activeSeatLiftY: wp0.seatLiftY ?? preset.seatLiftY ?? 0,
          activeHoldingCafeItemId: wp0.holdingCafeItemId ?? null,
          navPath: [],
          navWaypointIndex: 0,
          navPathGoalKey: '',
          stuckTimer: 0,
          lastProgressX: wp0.x,
          lastProgressZ: wp0.z,
          avoidSide: 0,
          avoidTimer: 0,
          seatOverride: null,
          seedPhase,
          nextFishCastSec: 7.5 + (idx % 4) * 3.2,
          glbUpgraded: false,
          rodUpgraded: !hasFishingStop,
        };
      },
    );

    const secondaryLodFrustum = new THREE.Frustum();
    const secondaryLodProjScreenMatrix = new THREE.Matrix4();
    const secondaryLodCamPos = new THREE.Vector3();
    const secondaryLodSphereScratch = new THREE.Sphere(new THREE.Vector3(), 3.0);
    let hasSecondaryLodFrustum = false;
    const syncSecondaryLodFrustum = () => {
      camera.updateMatrixWorld();
      secondaryLodProjScreenMatrix.multiplyMatrices(
        camera.projectionMatrix,
        camera.matrixWorldInverse,
      );
      secondaryLodFrustum.setFromProjectionMatrix(secondaryLodProjScreenMatrix);
      secondaryLodCamPos.copy(camera.position);
      hasSecondaryLodFrustum = true;
    };
    const resolveRigSecondaryPhysicsLod = (
      rootPos: THREE.Vector3,
      isPlayer = false,
      radiusMarginM = 3.0,
    ): SecondaryPhysicsLodMode => {
      if (isPlayer) return 'full';
      if (!hasSecondaryLodFrustum) {
        syncSecondaryLodFrustum();
      }
      secondaryLodSphereScratch.center.set(rootPos.x, rootPos.y + 0.95, rootPos.z);
      secondaryLodSphereScratch.radius = radiusMarginM;
      const inFrustum = secondaryLodFrustum.intersectsSphere(secondaryLodSphereScratch);
      if (!inFrustum) return 'sleep';
      const camDist = Math.hypot(
        rootPos.x - secondaryLodCamPos.x,
        rootPos.y + 0.95 - secondaryLodCamPos.y,
        rootPos.z - secondaryLodCamPos.z,
      );
      return resolveSecondaryPhysicsLod({
        cameraDistanceM: camDist,
        inFrustum,
        isPlayer: false,
      });
    };
    const resolveWrappedWorldSecondaryLod = (
      wx: number,
      wy: number,
      wz: number,
      isPlayer = false,
      isFlatIndoor = false,
      pivotX = 0,
      pivotZ = 0,
    ): SecondaryPhysicsLodMode => {
      if (isPlayer) return 'full';
      if (!hasSecondaryLodFrustum) {
        syncSecondaryLodFrustum();
      }
      const rx = isFlatIndoor ? wx : pivotX + getPlanetShortestDelta(wx, pivotX);
      const rz = isFlatIndoor ? wz : pivotZ + getPlanetShortestDelta(wz, pivotZ);
      secondaryLodSphereScratch.center.set(rx, wy + 0.95, rz);
      secondaryLodSphereScratch.radius = 3.5;
      const inFrustum = secondaryLodFrustum.intersectsSphere(secondaryLodSphereScratch);
      if (!inFrustum) return 'sleep';
      const camDist = Math.hypot(
        rx - secondaryLodCamPos.x,
        wy + 0.95 - secondaryLodCamPos.y,
        rz - secondaryLodCamPos.z,
      );
      return resolveSecondaryPhysicsLod({
        cameraDistanceM: camDist,
        inFrustum,
        isPlayer: false,
      });
    };

    const hideAllCityAmbientNpcs = () => {
      for (let i = 0; i < cityAmbientNpcs.length; i++) {
        const npc = cityAmbientNpcs[i];
        npc.root.visible = false;
        npc.nameplate.sprite.visible = false;
      }
    };

    let npcAnimLodTick = 0;
    const npcAvoidanceCapsulesScratch: PedestrianAvoidanceCapsule2D[] = [];
    const npcAvoidanceResultScratch: LocalPedestrianAvoidanceResult = {
      dirX: 0,
      dirZ: 0,
      speedScale: 1,
      avoidSide: 0,
      avoidTimer: 0,
      blocked: false,
    };
    const upgradeAmbientNpcRigIfNeeded = (
      npc: CityAmbientNpcController,
      assetsOverride?: LoadedBlitzAssets | null,
    ): boolean => {
      const assets = assetsOverride ?? loadedBlitzAssets ?? getCachedLoadedBlitzAssets();
      const playerFemaleGlb = assets?.playerFemaleGlb ?? earlyLoadedPlayerFemaleGltf;
      const playerMaleGlb = assets?.playerMaleGlb ?? earlyLoadedPlayerMaleGltf;
      const ambientFemaleGlb =
        assets?.ambientFemaleNpcGlb ??
        earlyLoadedAmbientFemaleGlb ??
        playerFemaleGlb;
      const ambientMaleGlb =
        assets?.ambientMaleNpcGlb ??
        earlyLoadedAmbientMaleGlb ??
        playerMaleGlb;
      const fishingRodGlb = assets?.fishingRodGltf;
      const hasAnyFishingStop =
        npc.preset.activity === 'fishing' ||
        npc.preset.waypoints.some((w) => w.activity === 'fishing');
      const citizenGlbs = getCachedLoadedCitizenGlbs();
      const bespokeCitizenGlb =
        npc.preset.id === 'city_plaza_raka'
          ? ambientMaleGlb
          : npc.preset.id === 'city_plaza_nadia'
            ? (assets?.nadiaCustomGlb ?? citizenGlbs.nadiaCustomGlb)
            : npc.preset.id === 'citizen_mira'
              ? (assets?.miraCustomGlb ?? citizenGlbs.miraCustomGlb)
              : npc.preset.id === 'citizen_tari'
                ? (assets?.tariCustomGlb ?? citizenGlbs.tariCustomGlb)
                : npc.preset.id === 'citizen_bima'
                  ? (assets?.bimaCustomGlb ?? citizenGlbs.bimaCustomGlb)
                  : npc.preset.id === 'citizen_kenji'
                    ? (assets?.kenjiCustomGlb ?? citizenGlbs.kenjiCustomGlb)
                    : undefined;
      const requiresBespokeCitizenGlb =
        npc.preset.id === 'city_plaza_raka' ||
        npc.preset.id === 'city_plaza_nadia' ||
        npc.preset.id === 'citizen_mira' ||
        npc.preset.id === 'citizen_tari' ||
        npc.preset.id === 'citizen_bima' ||
        npc.preset.id === 'citizen_kenji';
      const targetGlb = requiresBespokeCitizenGlb
        ? bespokeCitizenGlb
        : npc.preset.baseGlbVariant === 'player'
          ? npc.preset.gender === 'male'
            ? playerMaleGlb ?? ambientMaleGlb
            : playerFemaleGlb ?? ambientFemaleGlb
          : npc.preset.gender === 'male'
            ? ambientMaleGlb
            : ambientFemaleGlb;
      const needAvatarUpgrade = Boolean(targetGlb) && !npc.glbUpgraded;
      const needRodUpgrade =
        !npc.rodUpgraded &&
        hasAnyFishingStop &&
        Boolean(fishingRodGlb) &&
        Boolean(targetGlb);
      if ((!needAvatarUpgrade && !needRodUpgrade) || !targetGlb) {
        return false;
      }
      const hasFullModularOutfit = Boolean(
        npc.preset.equippedCostumeUrl ||
          npc.preset.equippedHairUrl ||
          npc.preset.equippedLegsUrl ||
          npc.preset.equippedFeetUrl,
      );
      npc.bodyGroup.userData.desiredModularOutfit = hasFullModularOutfit
        ? {
            costumeUrl: npc.preset.equippedCostumeUrl,
            hairUrl: npc.preset.equippedHairUrl,
            torsoUrl: npc.preset.equippedTorsoUrl,
            legsUrl: npc.preset.equippedLegsUrl,
            feetUrl: npc.preset.equippedFeetUrl,
          }
        : undefined;
      npc.bodyGroup.userData.desiredTorsoAssetUrl = hasFullModularOutfit
        ? null
        : (npc.preset.equippedTorsoUrl ?? null);
      npc.bodyGroup.userData.citizenClothingTintHex =
        npc.preset.disableClothingTint ? null : (npc.preset.clothingTintHex ?? null);
      upgradeBuddyRigWithCharBuddiesGlb(
        npc.rig,
        targetGlb,
        undefined,
        hasAnyFishingStop ? fishingRodGlb : undefined,
      );
      applyAmbientNpcClipOverrides(npc.rig, npc.preset);
      if (
        npc.preset.clothingTintHex &&
        !npc.preset.disableClothingTint &&
        !npc.rig.customGlbController?.glbRoot?.userData?.isBlitzModularDoll
      ) {
        applyCitizenClothingTint(npc.rig, npc.preset.clothingTintHex);
      }
      npc.rig.weaponRigGroup.visible = false;
      npc.rig.pistolGroup.visible = false;
      npc.glbUpgraded = true;
      if (hasAnyFishingStop && fishingRodGlb) {
        npc.rodUpgraded = true;
        npc.rig.fishingPoseState = {
          phase: 'nibble',
          isReeling: false,
          isSurging: false,
          tension: 0.12,
          rodBend: 0.08,
          reelAngle: 0,
          castPower: 0.5,
          castProgress: 1,
        };
      }
      return true;
    };

    const npcPortraitStudio = createNpcPortraitStudio();
    const prioritizedNpcPortraitIds = new Set<CitizenId>();
    const ALL_PORTRAIT_CITIZEN_IDS: readonly CitizenId[] = [
      'npc_hana',
      'npc_kai',
      'city_plaza_nadia',
      'citizen_mira',
      'citizen_tari',
      'city_plaza_raka',
      'citizen_bima',
      'citizen_kenji',
    ];
    let lastNpcPortraitCaptureMs = 0;

    const handleNpcPortraitRequestEvent = (ev: Event) => {
      const detail = (ev as CustomEvent<{ citizenId?: CitizenId }>).detail;
      const cid = detail?.citizenId;
      if (cid && !hasNpcPortraitPair(cid)) {
        prioritizedNpcPortraitIds.add(cid);
      }
    };
    window.addEventListener(NPC_PORTRAIT_REQUEST_EVENT, handleNpcPortraitRequestEvent);

    const isNpcRigReadyForStudioCapture = (
      rig: ReturnType<typeof buildProceduralBuddyAvatar>,
      bodyGroup: THREE.Group,
    ): boolean => {
      if (!rig.customGlbController?.glbRoot) return false;
      if (bodyGroup.userData?.desiredModularOutfit) {
        const seq = bodyGroup.userData.modularOutfitSeq as number | undefined;
        const doneSeq = bodyGroup.userData.modularOutfitCompletedSeq as number | undefined;
        if (!seq || doneSeq !== seq) return false;
      }
      return true;
    };

    const stepNpcPortraitCaptureQueue = (nowMs: number) => {
      if (worldModeRef.current === 'warzone') return;
      const hasPriority = prioritizedNpcPortraitIds.size > 0;
      if (!hasPriority && nowMs - lastNpcPortraitCaptureMs < 220) return;

      const candidateOrder: CitizenId[] = hasPriority
        ? [...prioritizedNpcPortraitIds]
        : [...ALL_PORTRAIT_CITIZEN_IDS];

      for (const cid of candidateOrder) {
        if (hasNpcPortraitPair(cid)) {
          prioritizedNpcPortraitIds.delete(cid);
          continue;
        }
        let targetRig: ReturnType<typeof buildProceduralBuddyAvatar> | null = null;
        let targetBody: THREE.Group | null = null;

        if (cid === 'npc_hana') {
          targetRig = lobbyCafeNpc.npcRig;
          targetBody = lobbyCafeNpc.bodyGrp;
        } else if (cid === 'npc_kai') {
          targetRig = beachHouseNpc.npcRig;
          targetBody = beachHouseNpc.bodyGrp;
        } else {
          const ambient = cityAmbientNpcs.find((n) => n.preset.id === cid);
          if (ambient) {
            if (!ambient.glbUpgraded) {
              upgradeAmbientNpcRigIfNeeded(ambient);
            }
            targetRig = ambient.rig;
            targetBody = ambient.bodyGroup;
          }
        }

        if (!targetRig || !targetBody) continue;
        if (!isNpcRigReadyForStudioCapture(targetRig, targetBody)) continue;

        const vpW = container.clientWidth || window.innerWidth;
        const vpH = container.clientHeight || window.innerHeight;
        const captured = npcPortraitStudio.captureNpcPhotos(
          renderer,
          cid,
          targetRig,
          targetBody,
          vpW,
          vpH,
        );
        if (captured) {
          setNpcPortraitPair(cid, captured);
          prioritizedNpcPortraitIds.delete(cid);
          lastNpcPortraitCaptureMs = nowMs;
        }
        // Capture at most one NPC per frame to keep frame pacing silky smooth
        break;
      }
    };

    const updateCityAmbientNpcsFrame = (
      dt: number,
      timeSec: number,
      nowMs: number,
      focusX: number,
      focusZ: number,
      playerX: number,
      playerZ: number,
      playerIsSitting: boolean,
      planetPivotX: number,
      planetPivotZ: number,
      kCurve: number,
      shouldShowAmbientNpcs: boolean,
      portraitOverride?: { citizenId: string; faceCamYaw: number } | null,
      isFlyInLightweightMode = false,
      worldClockHour = 12,
    ) => {
      npcAnimLodTick++;
      if (!shouldShowAmbientNpcs) {
        let prewarmedHiddenThisFrame = false;
        for (let i = 0; i < cityAmbientNpcs.length; i++) {
          const npc = cityAmbientNpcs[i];
          npc.root.visible = false;
          npc.nameplate.sprite.visible = false;
          if (!prewarmedHiddenThisFrame && (!npc.glbUpgraded || !npc.rodUpgraded)) {
            if (upgradeAmbientNpcRigIfNeeded(npc)) {
              prewarmedHiddenThisFrame = true;
            }
          }
          if (npc.rig.customGlbController) {
            npc.rig.customGlbController.lastStepTimeMs = nowMs;
          }
        }
        return;
      }

      syncSecondaryLodFrustum();

      // Lightweight fast-path during registered-user camera fly-in (`fly_to_plaza` -> `gameplay`):
      // Pre-warmed NPCs stand/sit at their initial Plaza anchors without A* pathfinding or multi-capsule collision spikes.
      if (isFlyInLightweightMode) {
        for (let i = 0; i < cityAmbientNpcs.length; i++) {
          const npc = cityAmbientNpcs[i];
          const distFromFocus = Math.hypot(npc.x - focusX, npc.z - focusZ);
          const visibleNow = distFromFocus <= 78.0;
          npc.root.visible = visibleNow;
          npc.nameplate.sprite.visible = false;
          if (!visibleNow) {
            if (npc.rig.customGlbController) {
              npc.rig.customGlbController.lastStepTimeMs = nowMs;
            }
            continue;
          }
          upgradeAmbientNpcRigIfNeeded(npc);
          const { seatFacingYaw, renderX, groundY, renderZ } = resolveCitizenRenderAnchor(
            npc,
            npc.x,
            npc.z,
            npc.yaw,
          );
          const renderYaw = npc.isSitting ? seatFacingYaw : npc.yaw;
          npc.shadowMesh.visible = !npc.isSitting;
          npc.bodyGroup.rotation.set(0, renderYaw + Math.PI / 2, 0);
          npc.bodyGroup.position.y = npc.isSitting ? npc.activeSeatLiftY + 0.178 : 0;
          applyPlanetCurvatureToObject(
            npc.root,
            renderX,
            groundY,
            renderZ,
            planetPivotX,
            planetPivotZ,
            0,
            kCurve,
          );
          if (npc.rig.customGlbController) {
            npc.rig.customGlbController.lastStepTimeMs = nowMs;
          }
        }
        return;
      }

      const pedestrianNavGrid = getPedestrianNavGrid();
      const tramStateNow = cityTram.getState();
      const auditedWorld = getAuditedStaticWorldStructures(getStaticWorldStructures());
      const sharedDynamicObbs: DynamicObbObstacle2D[] = getCityTramCollisionObbs(tramStateNow).map(
        (sec) => ({
          x: sec.x,
          z: sec.z,
          halfX: sec.halfX,
          halfZ: sec.halfZ,
          rotY: sec.yaw,
          vx: sec.forwardX * CITY_TRAM_SPEC.cruiseSpeed,
          vz: sec.forwardZ * CITY_TRAM_SPEC.cruiseSpeed,
        }),
      );
      if (cityLightingAndTraffic.rootGroup.visible) {
        const trafficBoxes = cityLightingAndTraffic.getVehicleCollisionBoxes();
        for (let tvi = 0; tvi < trafficBoxes.length; tvi++) {
          const box = trafficBoxes[tvi];
          sharedDynamicObbs.push({
            x: box.x,
            z: box.z,
            halfX: box.halfWidth,
            halfZ: box.halfLength,
            rotY: box.yaw,
            vx: box.vx,
            vz: box.vz,
          });
        }
      }
      const sharedDynamicCircles: DynamicCircleObstacle2D[] = [];
      for (const tr of trees) {
        if (!tr.alive) continue;
        sharedDynamicCircles.push({ x: tr.x, z: tr.z, radius: 0.98 * tr.scale });
      }
      for (const standingNpc of [lobbyCafeNpc, beachHouseNpc]) {
        if (!standingNpc?.npcGrp?.visible) continue;
        sharedDynamicCircles.push({
          x: standingNpc.npcGrp.position.x,
          z: standingNpc.npcGrp.position.z,
          radius: 0.56,
        });
      }
      const solidBenchProps: Array<{
        x: number;
        z: number;
        halfX?: number;
        halfZ?: number;
        rotY: number;
        radius: number;
        isBench: boolean;
      }> = [];
      for (const mp of activeMapProps) {
        if (
          !mp.alive ||
          !mp.wrapper.visible ||
          mp.category !== 'solid' ||
          (mp.kind === 'explosive_barrel' && cityArenaMode === 'safezone')
        ) {
          continue;
        }
        const isBenchProp = mp.kind === 'bench';
        if (!isBenchProp) {
          if (mp.halfX !== undefined && mp.halfZ !== undefined) {
            sharedDynamicObbs.push({
              x: mp.x,
              z: mp.z,
              halfX: mp.halfX,
              halfZ: mp.halfZ,
              rotY: mp.rotY,
            });
          } else {
            sharedDynamicCircles.push({ x: mp.x, z: mp.z, radius: mp.radius });
          }
        } else {
          solidBenchProps.push({
            x: mp.x,
            z: mp.z,
            halfX: mp.halfX,
            halfZ: mp.halfZ,
            rotY: mp.rotY,
            radius: mp.radius,
            isBench: true,
          });
        }
      }

      let upgradedThisFrame = false;
      let aStarCitizenPlansThisFrame = 0;

      interface NpcFrameStepState {
        npc: CityAmbientNpcController;
        isTalkingWithPlayer: boolean;
        prevX: number;
        prevZ: number;
        curX: number;
        curZ: number;
        vx: number;
        vz: number;
        exemptSeat: { x: number; z: number } | null;
        stepped: ReturnType<typeof stepCityAmbientNpcSchedule>;
      }
      const steppedStates: NpcFrameStepState[] = [];
      const invDt = dt > 1e-4 ? 1 / dt : 0;

      const anchorPlayerForNpcCluster =
        worldModeRef.current !== 'warzone' &&
        npcCameraMode === 'none' &&
        Boolean(playerUnit?.alive) &&
        !mountedTank &&
        ridingTramCarIdx === null;
      npcAvoidanceCapsulesScratch.length = 0;
      for (let j = 0; j < cityAmbientNpcs.length; j++) {
        const other = cityAmbientNpcs[j];
        npcAvoidanceCapsulesScratch.push({
          id: other.preset.id,
          x: other.x,
          z: other.z,
          vx: other.isMoving ? Math.cos(other.yaw) * other.speedMps : 0,
          vz: other.isMoving ? -Math.sin(other.yaw) * other.speedMps : 0,
          radius: AMBIENT_NPC_CAPSULE_RADIUS,
          groundY: getTerrainElevation(other.x, other.z),
          isSitting: other.isSitting,
        });
      }
      if (anchorPlayerForNpcCluster && playerUnit) {
        npcAvoidanceCapsulesScratch.push({
          id: '__anchored_player__',
          x: playerUnit.x,
          z: playerUnit.z,
          vx: playerUnit.vx,
          vz: playerUnit.vz,
          radius: PLAYER_FOOT_CAPSULE_RADIUS,
          groundY: getTerrainElevation(playerUnit.x, playerUnit.z),
        });
      }

      for (let i = 0; i < cityAmbientNpcs.length; i++) {
        const npc = cityAmbientNpcs[i];
        const prevX = npc.x;
        const prevZ = npc.z;
        const isTalkingWithPlayer = activeCitizenDialogueId === npc.preset.id;
        const isPairedWithPlayer = Boolean(
          activePairedSession &&
            activePairedSession.partnerKind === 'ambient_npc' &&
            activePairedSession.targetId === npc.preset.id,
        );
        const isRidingWithPlayer = Boolean(
          activeRideTogether &&
            activeRideTogether.citizenId === npc.preset.id &&
            scooterRideState &&
            scooterRideState.kind === 'electric_scooter_bike' &&
            playerUnit &&
            playerUnit.alive,
        );
        const isWalkingWithPlayer = Boolean(
          activeWalkTogether &&
            activeWalkTogether.citizenId === npc.preset.id &&
            playerUnit &&
            playerUnit.alive &&
            worldModeRef.current !== 'warzone' &&
            npcCameraMode === 'none',
        );
        const wasTalkingPrev = npcWasTalkingMap.get(npc.preset.id) ?? false;
        npcWasTalkingMap.set(npc.preset.id, isTalkingWithPlayer);
        const scheduledPatrolForLinger =
          resolveNpcScheduledPatrolWaypoints(npc.preset.id, worldClockHour) ?? npc.preset.waypoints;
        const lingerStep = stepNpcPostInteractionLinger({
          state: npcLingerStates.get(npc.preset.id) ?? createIdleNpcLingerState(),
          npcId: npc.preset.id,
          wasTalking: wasTalkingPrev,
          isTalking: isTalkingWithPlayer,
          npcX: npc.x,
          npcZ: npc.z,
          npcYaw: npc.yaw,
          playerX,
          playerZ,
          waypoints: scheduledPatrolForLinger,
          dt,
          suppressedByActivity: isWalkingWithPlayer || isRidingWithPlayer || isPairedWithPlayer,
        });
        npcLingerStates.set(npc.preset.id, lingerStep.state);
        if (lingerStep.endedThisFrame && lingerStep.resumeWaypointIdx !== null) {
          npc.waypointIdx = lingerStep.resumeWaypointIdx;
          npc.pauseTimer = 0;
          npc.navPath = [];
          npc.navWaypointIndex = 0;
          npc.navPathGoalKey = '';
        }
        let stepped: ReturnType<typeof stepCityAmbientNpcSchedule>;
        if (isRidingWithPlayer && scooterRideState && playerUnit) {
          const pillionTf = computeScooterPassengerTransform({
            driverX: playerUnit.x,
            driverZ: playerUnit.z,
            driverYaw: scooterRideState.yaw,
            groundY: scooterRideState.groundY,
            slopePitchX: scooterRideState.slopePitchX,
            leanRollZ: scooterRideState.pose?.leanRollZ ?? 0,
          });
          stepped = {
            x: pillionTf.worldX,
            z: pillionTf.worldZ,
            yaw: pillionTf.yaw,
            speedMps: 0,
            isMoving: false,
            isSitting: true,
            activeActivity: 'sit_relax',
            activeStatusLabel: 'RIDING TOGETHER',
            activeSeatLiftY: pillionTf.bodyLiftY - 0.178,
            activeHoldingCafeItemId: null,
            waypointIdx: npc.waypointIdx,
            pauseTimer: 0,
            navPath: [],
            navWaypointIndex: 0,
            navPathGoalKey: '',
            stuckTimer: 0,
            lastProgressX: pillionTf.worldX,
            lastProgressZ: pillionTf.worldZ,
            avoidSide: 0,
            avoidTimer: 0,
          };
        } else if (isWalkingWithPlayer && activeWalkTogether && playerUnit) {
          const walkRes = stepNpcWalkTogether({
            npcX: npc.x,
            npcZ: npc.z,
            npcYaw: npc.yaw,
            wasMoving: activeWalkTogether.wasMoving,
            playerX: playerUnit.x,
            playerZ: playerUnit.z,
            playerYaw: playerUnit.yaw,
            playerSpeedMps: Math.hypot(playerUnit.vx, playerUnit.vz),
            dt,
            navGrid: pedestrianNavGrid,
            navPath: activeWalkTogether.navPath,
            navWaypointIndex: activeWalkTogether.navWaypointIndex,
            replanTimerSec: activeWalkTogether.replanTimerSec,
          });
          activeWalkTogether.navPath = walkRes.navPath;
          activeWalkTogether.navWaypointIndex = walkRes.navWaypointIndex;
          activeWalkTogether.replanTimerSec = walkRes.replanTimerSec;
          activeWalkTogether.wasMoving = walkRes.isMoving;
          if (walkRes.shouldEndWalk) {
            activeWalkTogether = null;
            emitTogethernessStateSnapshot();
          }
          stepped = {
            x: walkRes.x,
            z: walkRes.z,
            yaw: walkRes.yaw,
            speedMps: walkRes.speedMps,
            isMoving: walkRes.isMoving,
            isSitting: false,
            activeActivity: 'walk_patrol',
            activeStatusLabel: 'WALKING TOGETHER',
            activeSeatLiftY: 0,
            activeHoldingCafeItemId: null,
            waypointIdx: npc.waypointIdx,
            pauseTimer: 0,
            navPath: walkRes.navPath,
            navWaypointIndex: walkRes.navWaypointIndex,
            navPathGoalKey: 'walk_together',
            stuckTimer: 0,
            lastProgressX: walkRes.x,
            lastProgressZ: walkRes.z,
            avoidSide: 0,
            avoidTimer: 0,
          };
        } else if (isPairedWithPlayer && activePairedSession) {
          stepped = {
            x: activePairedSession.anchorX,
            z: activePairedSession.anchorZ,
            yaw: activePairedSession.anchorYaw,
            speedMps: 0,
            isMoving: false,
            isSitting: false,
            activeActivity: npc.activeActivity,
            activeStatusLabel: activePairedSession.animLabel,
            activeSeatLiftY: 0,
            activeHoldingCafeItemId: null,
            waypointIdx: npc.waypointIdx,
            pauseTimer: npc.pauseTimer,
            navPath: npc.navPath,
            navWaypointIndex: npc.navWaypointIndex,
            navPathGoalKey: npc.navPathGoalKey,
            stuckTimer: 0,
            lastProgressX: activePairedSession.anchorX,
            lastProgressZ: activePairedSession.anchorZ,
            avoidSide: 0,
            avoidTimer: 0,
          };
        } else if (isTalkingWithPlayer && !npc.isSitting) {
          const targetTalkYaw =
            portraitOverride && portraitOverride.citizenId === npc.preset.id
              ? portraitOverride.faceCamYaw - Math.PI / 2
              : Math.atan2(-(playerZ - npc.z), playerX - npc.x);
          let dYaw = targetTalkYaw - npc.yaw;
          while (dYaw > Math.PI) dYaw -= Math.PI * 2;
          while (dYaw < -Math.PI) dYaw += Math.PI * 2;
          const maxTurnRate =
            portraitOverride && portraitOverride.citizenId === npc.preset.id ? 12.0 : 7.5;
          const turnStep = Math.max(-maxTurnRate * dt, Math.min(maxTurnRate * dt, dYaw));
          stepped = {
            x: npc.x,
            z: npc.z,
            yaw: npc.yaw + turnStep,
            speedMps: 0,
            isMoving: false,
            isSitting: false,
            activeActivity: npc.activeActivity,
            activeStatusLabel: npc.activeStatusLabel,
            activeSeatLiftY: npc.activeSeatLiftY,
            activeHoldingCafeItemId: npc.activeHoldingCafeItemId,
            waypointIdx: npc.waypointIdx,
            pauseTimer: npc.pauseTimer,
            navPath: npc.navPath,
            navWaypointIndex: npc.navWaypointIndex,
            navPathGoalKey: npc.navPathGoalKey,
            stuckTimer: 0,
            lastProgressX: npc.x,
            lastProgressZ: npc.z,
            avoidSide: 0,
            avoidTimer: 0,
          };
        } else if (lingerStep.isLingering) {
          stepped = {
            x: npc.x,
            z: npc.z,
            yaw: lingerStep.yaw,
            speedMps: 0,
            isMoving: false,
            isSitting: false,
            activeActivity: npc.activeActivity,
            activeStatusLabel: npc.activeStatusLabel,
            activeSeatLiftY: 0,
            activeHoldingCafeItemId: npc.activeHoldingCafeItemId,
            waypointIdx: npc.waypointIdx,
            pauseTimer: npc.pauseTimer,
            navPath: npc.navPath,
            navWaypointIndex: npc.navWaypointIndex,
            navPathGoalKey: npc.navPathGoalKey,
            stuckTimer: 0,
            lastProgressX: npc.x,
            lastProgressZ: npc.z,
            avoidSide: 0,
            avoidTimer: 0,
          };
        } else {
          const fwdX = Math.cos(npc.yaw);
          const fwdZ = -Math.sin(npc.yaw);
          const preSteerExemptSeat = resolveAmbientNpcExemptSeatPoint(
            npc.preset,
            npc.waypointIdx,
            npc.x,
            npc.z,
            npc.isSitting,
            npc.seatOverride,
          );
          const npcGroundY = getTerrainElevation(npc.x, npc.z);

          // Check whether the NPC's approached `sit_relax` bench/chair is already occupied;
          // if so, divert to an unoccupied nearby bench OR skip this stop and keep roaming.
          const wpLen = npc.preset.waypoints.length;
          const activeWpIdx = wpLen > 0 ? ((npc.waypointIdx % wpLen) + wpLen) % wpLen : 0;
          const activeTargetWp = wpLen > 0 ? npc.preset.waypoints[activeWpIdx] : undefined;
          const activeGoalIsSit =
            (activeTargetWp?.activity ?? npc.preset.activity) === 'sit_relax';
          const effectiveGoal =
            npc.seatOverride && npc.seatOverride.wpIdx === activeWpIdx
              ? npc.seatOverride
              : activeTargetWp;
          let targetSeatOccupied = false;
          let alternateSeatForNpc: ReturnType<typeof findNearestUnoccupiedSeatForNpc> = null;
          if (
            !npc.isSitting &&
            npc.pauseTimer <= 0 &&
            activeGoalIsSit &&
            effectiveGoal &&
            Math.hypot(effectiveGoal.x - npc.x, effectiveGoal.z - npc.z) <= 18.0 &&
            isOutdoorSeatOccupied(effectiveGoal, npc.preset.id)
          ) {
            targetSeatOccupied = true;
            npcAlternateOccupantsScratch.length = 0;
            if (playerUnit && playerUnit.alive && playerUnit.isSitting) {
              npcAlternateOccupantsScratch.push({
                id: '__local_player__',
                x: playerUnit.x,
                z: playerUnit.z,
                isSitting: true,
              });
            }
            for (let oi = 0; oi < cityAmbientNpcs.length; oi++) {
              const other = cityAmbientNpcs[oi];
              if (other.preset.id === npc.preset.id) continue;
              if (other.isSitting) {
                npcAlternateOccupantsScratch.push({
                  id: other.preset.id,
                  x: other.x,
                  z: other.z,
                  isSitting: true,
                });
              } else if (other.seatOverride) {
                npcAlternateOccupantsScratch.push({
                  id: other.preset.id,
                  x: other.seatOverride.x,
                  z: other.seatOverride.z,
                  isSitting: true,
                });
              }
            }
            for (const av of remotePlayerAvatars.values()) {
              if (!av.root.visible || !av.peer.isSitting) continue;
              npcAlternateOccupantsScratch.push({
                id: av.peer.sessionId,
                x: av.renderX,
                z: av.renderZ,
                isSitting: true,
              });
            }
            alternateSeatForNpc = findNearestUnoccupiedSeatForNpc({
              targetX: effectiveGoal.x,
              targetZ: effectiveGoal.z,
              npcX: npc.x,
              npcZ: npc.z,
              npcId: npc.preset.id,
              candidateSeats: LOBBY_SEAT_SPOTS,
              occupants: npcAlternateOccupantsScratch,
              maxSearchRadiusM: 16.0,
            });
          }

          // Curb, lane-divider & red-light crosswalk safety: yield before stepping onto a roadway OR
          // crossing from the parallel outer car lane onto the inner Halte-side tram track.
          const nextNavNode =
            npc.navPath.length > 0 && npc.navWaypointIndex < npc.navPath.length
              ? npc.navPath[npc.navWaypointIndex]
              : null;
          const headingDx = (nextNavNode ? nextNavNode.x : npc.x + fwdX * 3.0) - npc.x;
          const headingDz = (nextNavNode ? nextNavNode.z : npc.z + fwdZ * 3.0) - npc.z;
          const headingDist = Math.hypot(headingDx, headingDz);
          const probeDist = Math.min(3.4, Math.max(1.4, headingDist));
          const probeX = headingDist > 0.05 ? npc.x + (headingDx / headingDist) * probeDist : npc.x;
          const probeZ = headingDist > 0.05 ? npc.z + (headingDz / headingDist) * probeDist : npc.z;
          const yieldForTram =
            !npc.isSitting &&
            npc.pauseTimer <= 0 &&
            shouldPedestrianYieldForTramOrSignal({
              x: npc.x,
              z: npc.z,
              probeX,
              probeZ,
              tramState: tramStateNow,
              signalState: plazaTrafficSignalState,
              eastSignalState: eastTrafficSignalState,
            });

          // Deterministic multi-waypoint persona patrol loop (LLM never decides movement):
          // uses `getNpcPersona(npcId)?.schedule` anchors so NPCs actively patrol their
          // assigned territory instead of freezing on 1 bench or stacking on shared benches.
          const scheduledPatrolWaypoints = resolveNpcScheduledPatrolWaypoints(
            npc.preset.id,
            worldClockHour,
          );
          const effectiveSchedulePreset =
            scheduledPatrolWaypoints && scheduledPatrolWaypoints.length > 0
              ? {
                  ...npc.preset,
                  waypoints: scheduledPatrolWaypoints,
                }
              : npc.preset;

          stepped = stepCityAmbientNpcSchedule({
            preset: effectiveSchedulePreset,
            x: npc.x,
            z: npc.z,
            yaw: npc.yaw,
            waypointIdx: npc.waypointIdx,
            pauseTimer: npc.pauseTimer,
            dt,
            elapsedSec: timeSec + npc.seedPhase,
            navGrid: pedestrianNavGrid,
            navPath: npc.navPath,
            navWaypointIndex: npc.navWaypointIndex,
            navPathGoalKey: npc.navPathGoalKey,
            stuckTimer: npc.stuckTimer,
            lastProgressX: npc.lastProgressX,
            lastProgressZ: npc.lastProgressZ,
            avoidSide: npc.avoidSide,
            avoidTimer: npc.avoidTimer,
            seatOverride: npc.seatOverride,
            isTargetSeatOccupied: targetSeatOccupied,
            alternateSeat: alternateSeatForNpc,
            yieldForHazard: yieldForTram,
            isDirectTargetClear: (fromX, fromZ, toX, toZ, isSitGoal) =>
              isSegmentClearOfAuditedStaticObstacles2D({
                fromX,
                fromZ,
                toX,
                toZ,
                radius: AMBIENT_NPC_CAPSULE_RADIUS,
                audited: auditedWorld,
                dynamicObbs: sharedDynamicObbs,
                dynamicCircles: sharedDynamicCircles,
                exemptSeatPoint: isSitGoal ? { x: toX, z: toZ } : preSteerExemptSeat,
              }),
            localAvoidance: (sample) =>
              computeLocalPedestrianAvoidance2D(
                {
                  selfId: npc.preset.id,
                  x: sample.x,
                  z: sample.z,
                  dirX: sample.dirX,
                  dirZ: sample.dirZ,
                  radius: AMBIENT_NPC_CAPSULE_RADIUS,
                  selfGroundY: npcGroundY,
                  distToSteerTarget: sample.distToSteer,
                  distToFinal: sample.distToFinal,
                  isFinalGoal: sample.isFinalTarget,
                  dt,
                  audited: auditedWorld,
                  dynamicObbs: sharedDynamicObbs,
                  dynamicCircles: sharedDynamicCircles,
                  characterCapsules: npcAvoidanceCapsulesScratch,
                  exemptSeatPoint: preSteerExemptSeat,
                  stayOffNonCrosswalkRoads: true,
                  avoidSide: sample.avoidSide,
                  avoidTimer: sample.avoidTimer,
                },
                npcAvoidanceResultScratch,
              ),
            canReplan: aStarCitizenPlansThisFrame < 1,
            onReplan: () => {
              aStarCitizenPlansThisFrame++;
            },
          });
        }

        let curX = stepped.x;
        let curZ = stepped.z;
        let vx = stepped.isMoving ? (stepped.x - prevX) * invDt : 0;
        let vz = stepped.isMoving ? (stepped.z - prevZ) * invDt : 0;
        const exemptSeat = resolveAmbientNpcExemptSeatPoint(
          npc.preset,
          stepped.waypointIdx,
          curX,
          curZ,
          stepped.isSitting,
          stepped.seatOverride ?? null,
        );

        // Enforce unified static world, shoreline/water, dynamic prop, and stair guard collisions
        if (!stepped.isSitting && !isTalkingWithPlayer) {
          const staticRes = resolveGroundMoverAuditedCollisions2D({
            x: curX,
            z: curZ,
            vx,
            vz,
            radius: AMBIENT_NPC_CAPSULE_RADIUS,
            audited: auditedWorld,
            prevX,
            prevZ,
            waterMarginM: 0.22,
            restitution: 0.0,
            iterations: 2,
            stayOffNonCrosswalkRoads: true,
            exemptSeatPoint: exemptSeat,
          });
          curX = staticRes.x;
          curZ = staticRes.z;
          vx = staticRes.vx;
          vz = staticRes.vz;

          if (solidBenchProps.length > 0) {
            const benchObbs: DynamicObbObstacle2D[] = [];
            const benchCircles: DynamicCircleObstacle2D[] = [];
            for (let bi = 0; bi < solidBenchProps.length; bi++) {
              const bp = solidBenchProps[bi];
              if (
                exemptSeat &&
                Math.hypot(bp.x - exemptSeat.x, bp.z - exemptSeat.z) <= 1.35
              ) {
                continue;
              }
              if (bp.halfX !== undefined && bp.halfZ !== undefined) {
                benchObbs.push({
                  x: bp.x,
                  z: bp.z,
                  halfX: bp.halfX,
                  halfZ: bp.halfZ,
                  rotY: bp.rotY,
                });
              } else {
                benchCircles.push({ x: bp.x, z: bp.z, radius: bp.radius });
              }
            }
            if (benchObbs.length > 0 || benchCircles.length > 0) {
              const benchRes = resolveCharacterAgainstDynamicObstacles2D({
                x: curX,
                z: curZ,
                vx,
                vz,
                radius: AMBIENT_NPC_CAPSULE_RADIUS,
                obbs: benchObbs,
                circles: benchCircles,
                restitution: 0.0,
              });
              curX = benchRes.x;
              curZ = benchRes.z;
              vx = benchRes.vx;
              vz = benchRes.vz;
            }
          }

          const dynRes = resolveCharacterAgainstDynamicObstacles2D({
            x: curX,
            z: curZ,
            vx,
            vz,
            radius: AMBIENT_NPC_CAPSULE_RADIUS,
            obbs: sharedDynamicObbs,
            circles: sharedDynamicCircles,
            restitution: 0.0,
          });
          curX = dynRes.x;
          curZ = dynRes.z;
          vx = dynRes.vx;
          vz = dynRes.vz;

          if (getPlanetShortestDistance(prevX, prevZ, curX, curZ) <= 2.6) {
            const stairGuard = resolveStaircaseAndElevationGuard2D({
              prevX,
              prevZ,
              nextX: curX,
              nextZ: curZ,
              vx,
              vz,
              radius: AMBIENT_NPC_CAPSULE_RADIUS,
            });
            curX = stairGuard.x;
            curZ = stairGuard.z;
            vx = stairGuard.vx;
            vz = stairGuard.vz;
          }
        }

        steppedStates.push({
          npc,
          isTalkingWithPlayer,
          prevX,
          prevZ,
          curX,
          curZ,
          vx,
          vz,
          exemptSeat,
          stepped,
        });
      }

      // Multi-iteration solid capsule separation across ALL Town Folks NPCs & anchored Player capsule
      const clusterBodies: CharacterCapsuleBody2D[] = steppedStates.map((st) => ({
        id: st.npc.preset.id,
        x: st.curX,
        z: st.curZ,
        vx: st.vx,
        vz: st.vz,
        radius: AMBIENT_NPC_CAPSULE_RADIUS,
        groundY: getTerrainElevation(st.curX, st.curZ),
        isSitting: st.stepped.isSitting,
        isTalking: st.isTalkingWithPlayer,
      }));
      if (anchorPlayerForNpcCluster && playerUnit && !activePairedSession) {
        clusterBodies.push({
          id: '__anchored_player__',
          x: playerUnit.x,
          z: playerUnit.z,
          vx: 0,
          vz: 0,
          radius: PLAYER_FOOT_CAPSULE_RADIUS,
          groundY: getTerrainElevation(playerUnit.x, playerUnit.z),
          immovable: true,
        });
      }
      resolveMultiIterationCapsuleCluster2D(clusterBodies, 3);

      for (let i = 0; i < steppedStates.length; i++) {
        const st = steppedStates[i];
        const body = clusterBodies[i];
        const { npc, stepped, isTalkingWithPlayer } = st;
        const isPairedNpcNow = Boolean(
          activePairedSession &&
            activePairedSession.partnerKind === 'ambient_npc' &&
            activePairedSession.targetId === npc.preset.id,
        );
        let finalX = isPairedNpcNow && activePairedSession ? activePairedSession.anchorX : body.x;
        let finalZ = isPairedNpcNow && activePairedSession ? activePairedSession.anchorZ : body.z;
        if (
          !stepped.isSitting &&
          !isTalkingWithPlayer &&
          !isPairedNpcNow &&
          (Math.abs(finalX - st.curX) > 1e-4 || Math.abs(finalZ - st.curZ) > 1e-4)
        ) {
          const postStatic = resolveGroundMoverAuditedCollisions2D({
            x: finalX,
            z: finalZ,
            vx: body.vx,
            vz: body.vz,
            radius: AMBIENT_NPC_CAPSULE_RADIUS,
            audited: auditedWorld,
            prevX: st.curX,
            prevZ: st.curZ,
            waterMarginM: 0.22,
            restitution: 0.0,
            iterations: 1,
            stayOffNonCrosswalkRoads: true,
            exemptSeatPoint: st.exemptSeat,
          });
          finalX = postStatic.x;
          finalZ = postStatic.z;
        }

        const wasMoving = npc.isMoving;
        const actualDisplacement = getPlanetShortestDistance(st.prevX, st.prevZ, finalX, finalZ);
        const actualSpeedMps = dt > 1e-4 ? actualDisplacement / dt : 0;
        const expectedStepDist = stepped.speedMps * dt;
        const moveRatio =
          stepped.isMoving && expectedStepDist > 1e-4
            ? Math.min(1.15, actualDisplacement / expectedStepDist)
            : 0;
        const effectiveIsMoving =
          stepped.isMoving && actualSpeedMps >= 0.22 && moveRatio >= 0.18;
        const effectiveSpeedMps = effectiveIsMoving ? actualSpeedMps : 0;

        npc.x = finalX;
        npc.z = finalZ;
        npc.yaw = stepped.yaw;
        npc.waypointIdx = stepped.waypointIdx;
        npc.pauseTimer = stepped.pauseTimer;
        npc.speedMps = effectiveSpeedMps;
        npc.isMoving = effectiveIsMoving;
        npc.isSitting = stepped.isSitting;
        npc.activeActivity = stepped.activeActivity;
        npc.activeStatusLabel = stepped.activeStatusLabel;
        npc.activeSeatLiftY = stepped.activeSeatLiftY;
        npc.activeHoldingCafeItemId = stepped.activeHoldingCafeItemId;
        npc.navPath = stepped.navPath;
        npc.navWaypointIndex = stepped.navWaypointIndex;
        npc.navPathGoalKey = stepped.navPathGoalKey;
        npc.stuckTimer = stepped.stuckTimer;
        npc.lastProgressX = stepped.lastProgressX;
        npc.lastProgressZ = stepped.lastProgressZ;
        npc.avoidSide = stepped.avoidSide;
        npc.avoidTimer = stepped.avoidTimer;
        npc.seatOverride = stepped.seatOverride ?? null;
        if (effectiveIsMoving) {
          const cadenceScale = Math.max(0.32, Math.min(1.05, moveRatio));
          npc.walkCycle +=
            dt *
            (stepped.activeActivity === 'jog_exercise' || stepped.speedMps >= 4.5
              ? 9.4
              : 6.4) *
            cadenceScale;
        }

        const seatConflict =
          npc.isSitting &&
          ((playerIsSitting && Math.hypot(playerX - finalX, playerZ - finalZ) < 0.9) ||
            cityAmbientNpcs.some(
              (other, oi) =>
                oi < i &&
                other.isSitting &&
                Math.hypot(other.x - finalX, other.z - finalZ) < 0.9,
            ));
        if (seatConflict) {
          npc.isSitting = false;
          npc.pauseTimer = 0;
          npc.seatOverride = null;
          npc.navPath = [];
          npc.navPathGoalKey = '';
        }
        const distFromFocus = Math.hypot(finalX - focusX, finalZ - focusZ);
        const visibleNow = distFromFocus <= 78.0;
        npc.root.visible = visibleNow;

        if (!visibleNow) {
          npc.nameplate.sprite.visible = false;
          if (npc.rig.customGlbController) {
            npc.rig.customGlbController.lastStepTimeMs = nowMs;
          }
          continue;
        }

        // Stagger shared GLB cloning to at most 1 nearby NPC per frame so Safezone FPS never spikes.
        if (!upgradedThisFrame || isTalkingWithPlayer) {
          if (upgradeAmbientNpcRigIfNeeded(npc)) {
            upgradedThisFrame = true;
          }
        }

        const { seatFacingYaw, renderX, groundY, renderZ } = resolveCitizenRenderAnchor(
          npc,
          finalX,
          finalZ,
          stepped.yaw,
        );
        const renderYaw = npc.isSitting ? seatFacingYaw : stepped.yaw;

        const isRidingPassengerNow = Boolean(
          activeRideTogether &&
            activeRideTogether.citizenId === npc.preset.id &&
            scooterRideState &&
            scooterRideState.kind === 'electric_scooter_bike',
        );
        npc.shadowMesh.visible = !npc.isSitting;
        if (isRidingPassengerNow && scooterRideState) {
          npc.bodyGroup.rotation.order = 'YXZ';
          npc.bodyGroup.rotation.set(
            scooterRideState.slopePitchX,
            renderYaw + Math.PI / 2,
            scooterRideState.pose?.leanRollZ ?? 0,
          );
          if (npc.rig.customGlbController?.clips.has('scooter_bike_idle.001')) {
            npc.rig.activeSocialClipName = 'scooter_bike_idle.001';
          }
        } else {
          npc.bodyGroup.rotation.set(0, renderYaw + Math.PI / 2, 0);
          if (npc.rig.activeSocialClipName === 'scooter_bike_idle.001') {
            npc.rig.activeSocialClipName = undefined;
          }
        }
        const sitLiftY = npc.isSitting ? npc.activeSeatLiftY + 0.178 : 0;
        npc.bodyGroup.position.y = sitLiftY;

        applyPlanetCurvatureToObject(
          npc.root,
          renderX,
          groundY,
          renderZ,
          planetPivotX,
          planetPivotZ,
          0,
          kCurve,
        );

        npc.nameplate.sprite.visible = false;

        if (distFromFocus <= 44.0 || isTalkingWithPlayer || isPairedNpcNow) {
          if (!hasSecondaryLodFrustum) {
            syncSecondaryLodFrustum();
          }
          secondaryLodSphereScratch.center.set(
            npc.root.position.x,
            npc.root.position.y + 0.95,
            npc.root.position.z,
          );
          secondaryLodSphereScratch.radius = 2.8;
          const isNpcInFrustum =
            isTalkingWithPlayer ||
            isPairedNpcNow ||
            secondaryLodFrustum.intersectsSphere(secondaryLodSphereScratch);

          if (!isNpcInFrustum && !upgradedThisFrame) {
            if (npc.rig.customGlbController) {
              npc.rig.customGlbController.lastStepTimeMs = nowMs;
            }
            continue;
          }

          const isCurrentlyFishing =
            npc.activeActivity === 'fishing' && !isTalkingWithPlayer && !isPairedNpcNow;
          let castRecoil = 0;
          if (isCurrentlyFishing && npc.rodUpgraded) {
            if (timeSec >= npc.nextFishCastSec) {
              castRecoil = 0.9;
              npc.nextFishCastSec = timeSec + 11.5 + ((i * 2.17) % 5.5);
            }
          }
          const shouldStepDetail =
            isTalkingWithPlayer ||
            isPairedNpcNow ||
            shouldStepCharacterDetailThisFrame(
              distFromFocus * distFromFocus,
              npcAnimLodTick,
              i,
              false,
              effectiveIsMoving || wasMoving || castRecoil > 0,
            );
          if (shouldStepDetail || upgradedThisFrame) {
            const stanceWeaponId = isCurrentlyFishing ? 'fishing_rod' : 'unarmed';
            const npcSecondaryLod = resolveRigSecondaryPhysicsLod(npc.root.position, false, 3.0);
            updateCharacterWeaponStance(
              npc.rig,
              stanceWeaponId,
              npc.walkCycle,
              effectiveIsMoving,
              false,
              0,
              castRecoil,
              0,
              'right',
              0,
              0,
              0.76,
              0,
              true,
              'front',
              1.0,
              renderYaw,
              effectiveSpeedMps,
              npc.isSitting,
              false,
              false,
              null,
              'idle',
              'chair',
              isTalkingWithPlayer ? null : npc.activeHoldingCafeItemId,
              npcSecondaryLod,
            );
            if (!isCurrentlyFishing) {
              npc.rig.weaponRigGroup.visible = false;
              npc.rig.pistolGroup.visible = false;
            }
          }
        } else if (npc.rig.customGlbController) {
          npc.rig.customGlbController.lastStepTimeMs = nowMs;
        }
      }

      // Merchant NPC (Hana / Kai) walk-together & ride-together updates
      if (
        activeRideTogether &&
        (activeRideTogether.npcId === 'hana' || activeRideTogether.npcId === 'kai') &&
        scooterRideState &&
        scooterRideState.kind === 'electric_scooter_bike' &&
        playerUnit &&
        playerUnit.alive
      ) {
        const mNpc = activeRideTogether.npcId === 'hana' ? lobbyCafeNpc : beachHouseNpc;
        if (mNpc?.npcGrp && mNpc?.npcRig) {
          const pillionTf = computeScooterPassengerTransform({
            driverX: playerUnit.x,
            driverZ: playerUnit.z,
            driverYaw: scooterRideState.yaw,
            groundY: scooterRideState.groundY,
            slopePitchX: scooterRideState.slopePitchX,
            leanRollZ: scooterRideState.pose?.leanRollZ ?? 0,
          });
          mNpc.npcGrp.position.set(
            pillionTf.worldX,
            pillionTf.worldY + pillionTf.bodyLiftY,
            pillionTf.worldZ,
          );
          mNpc.npcGrp.rotation.order = 'YXZ';
          mNpc.npcGrp.rotation.set(
            pillionTf.pitchX,
            pillionTf.yaw + Math.PI / 2,
            pillionTf.rollZ,
          );
          if (mNpc.npcRig.customGlbController?.clips.has('scooter_bike_idle.001')) {
            mNpc.npcRig.activeSocialClipName = 'scooter_bike_idle.001';
          }
          updateCharacterWeaponStance(
            mNpc.npcRig,
            'unarmed',
            0,
            false,
            false,
            0,
            0,
            0,
            'right',
            0,
            0,
            0.76,
            0,
            true,
            'front',
            1.0,
            pillionTf.yaw,
            0,
            true,
            false,
            false,
            null,
            'idle',
            'chair',
            null,
          );
        }
      } else if (
        activeWalkTogether &&
        (activeWalkTogether.npcId === 'hana' || activeWalkTogether.npcId === 'kai') &&
        playerUnit &&
        playerUnit.alive &&
        worldModeRef.current !== 'warzone' &&
        npcCameraMode === 'none'
      ) {
        const mNpc = activeWalkTogether.npcId === 'hana' ? lobbyCafeNpc : beachHouseNpc;
        if (mNpc?.npcGrp && mNpc?.npcRig) {
          const curYaw = mNpc.npcGrp.rotation.y - Math.PI / 2;
          const walkRes = stepNpcWalkTogether({
            npcX: mNpc.npcGrp.position.x,
            npcZ: mNpc.npcGrp.position.z,
            npcYaw: curYaw,
            wasMoving: activeWalkTogether.wasMoving,
            playerX: playerUnit.x,
            playerZ: playerUnit.z,
            playerYaw: playerUnit.yaw,
            playerSpeedMps: Math.hypot(playerUnit.vx, playerUnit.vz),
            dt,
            navGrid: pedestrianNavGrid,
            navPath: activeWalkTogether.navPath,
            navWaypointIndex: activeWalkTogether.navWaypointIndex,
            replanTimerSec: activeWalkTogether.replanTimerSec,
          });
          activeWalkTogether.navPath = walkRes.navPath;
          activeWalkTogether.navWaypointIndex = walkRes.navWaypointIndex;
          activeWalkTogether.replanTimerSec = walkRes.replanTimerSec;
          activeWalkTogether.wasMoving = walkRes.isMoving;
          if (walkRes.isMoving) {
            activeWalkTogether.walkCycle += dt * Math.max(1.2, walkRes.speedMps) * 3.1;
          }
          if (walkRes.shouldEndWalk) {
            if (activeWalkTogether.savedMerchantAnchor) {
              const a = activeWalkTogether.savedMerchantAnchor;
              mNpc.npcGrp.position.set(a.x, a.y, a.z);
              mNpc.npcGrp.rotation.set(0, a.yaw, 0);
            }
            activeWalkTogether = null;
            emitTogethernessStateSnapshot();
          } else {
            const groundY = getTerrainElevation(walkRes.x, walkRes.z);
            mNpc.npcGrp.position.set(walkRes.x, groundY, walkRes.z);
            mNpc.npcGrp.rotation.set(0, walkRes.yaw + Math.PI / 2, 0);
            updateCharacterWeaponStance(
              mNpc.npcRig,
              'unarmed',
              activeWalkTogether.walkCycle,
              walkRes.isMoving,
              false,
              0,
              0,
              0,
              'right',
              0,
              0,
              0.76,
              0,
              true,
              'front',
              1.0,
              walkRes.yaw,
              walkRes.speedMps,
              false,
              false,
              false,
              null,
              'idle',
              'chair',
              null,
            );
          }
        }
      }
    };

    // =========================================================================
    // BOTANICAL GLASSHOUSE CAFE ("RUMAH KACA CAFE") EXTERIOR DOOR PAD & 3D INTERIOR
    // =========================================================================
    const cafeExteriorDoorPad = buildGlowingDoorFloorArrowPad();
    cafeExteriorDoorPad.group.position.set(
      CAFE_EXTERIOR_DOOR_TRIGGER.x,
      CAFE_EXTERIOR_DOOR_TRIGGER.deckY + 0.04,
      CAFE_EXTERIOR_DOOR_TRIGGER.z,
    );
    scene.add(cafeExteriorDoorPad.group);

    // Glowing Floor Ring + 3D Triangle for Outdoor Private House / Model Estate Entrance Door
    const houseExteriorDoorPad = buildGlowingDoorFloorArrowPad();
    houseExteriorDoorPad.group.visible = false;
    scene.add(houseExteriorDoorPad.group);

    // Compact ring-less 3D interaction triangle ("segitiga interaksi di bawah") in front of Urban Scooter Showroom A-Frame sign
    const scooterShopChevron = buildCompactInteractiveChevronMarker(0.18, 0.34, '#38bdf8');
    scooterShopChevron.group.name = 'UrbanScooterShowroomInteractionChevron';
    scooterShopChevron.group.position.set(
      URBAN_SCOOTER_SHOP_TRIGGER.x,
      URBAN_SCOOTER_SHOP_TRIGGER.deckY + URBAN_SCOOTER_SHOP_TRIGGER.markerOffsetY,
      URBAN_SCOOTER_SHOP_TRIGGER.z,
    );
    scene.add(scooterShopChevron.group);

    // Compact ring-less 3D interaction triangle beside the Fashion & Apparel Boutique wooden A-Frame sign
    const fashionShopChevron = buildCompactInteractiveChevronMarker(0.18, 0.34, '#38bdf8');
    fashionShopChevron.group.name = 'FashionBoutiqueInteractionChevron';
    fashionShopChevron.group.position.set(
      FASHION_BOUTIQUE_SHOP_TRIGGER.x,
      FASHION_BOUTIQUE_SHOP_TRIGGER.deckY + FASHION_BOUTIQUE_SHOP_TRIGGER.markerOffsetY,
      FASHION_BOUTIQUE_SHOP_TRIGGER.z,
    );
    scene.add(fashionShopChevron.group);

    // Compact ring-less 3D interaction triangle beside the Real Estate & Furniture Showroom wooden A-Frame sign
    const realEstateCatalogChevron = buildCompactInteractiveChevronMarker(0.18, 0.34, '#38bdf8');
    realEstateCatalogChevron.group.name = 'RealEstateCatalogInteractionChevron';
    realEstateCatalogChevron.group.position.set(
      REAL_ESTATE_CATALOG_TRIGGER.x,
      REAL_ESTATE_CATALOG_TRIGGER.deckY + REAL_ESTATE_CATALOG_TRIGGER.markerOffsetY,
      REAL_ESTATE_CATALOG_TRIGGER.z,
    );
    scene.add(realEstateCatalogChevron.group);

    // Compact ring-less 3D interaction triangle above the circular front medallion of Classic Plaza Manor Model House
    const modelHouseDoorChevron = buildCompactInteractiveChevronMarker(0.18, 0.34, '#38bdf8');
    modelHouseDoorChevron.group.name = 'PlazaModelHouseDoorInteractionChevron';
    modelHouseDoorChevron.group.position.set(
      PLAZA_MODEL_HOUSE_DOOR_TRIGGER.x,
      PLAZA_MODEL_HOUSE_DOOR_TRIGGER.deckY + PLAZA_MODEL_HOUSE_DOOR_TRIGGER.markerOffsetY,
      PLAZA_MODEL_HOUSE_DOOR_TRIGGER.z,
    );
    scene.add(modelHouseDoorChevron.group);

    // Compact ring-less 3D interaction triangle ("segitiga interaksi untuk masuk ke bangunan casino") in front of Grand Casino entrance steps
    const grandCasinoDoorChevron = buildCompactInteractiveChevronMarker(0.18, 0.34, '#38bdf8');
    grandCasinoDoorChevron.group.name = 'GrandCasinoDoorInteractionChevron';
